describe('Authentication - Incorrect Password Error Message', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display error message when user enters incorrect password', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Fill in valid email
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Fill in incorrect password
    cy.get('[data-testid="password-input"]').type('wrongpassword123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response
    cy.wait('@loginAttempt');

    // Assert error message is visible
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid password');

    // Assert error message has correct styling (red color indicator)
    cy.get('[data-testid="error-message"]')
      .should('have.css', 'color')
      .and('include', 'rgb(220, 53, 69)');

    // Assert password field is still visible for retry
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Assert login button is still enabled
    cy.get('[data-testid="login-button"]').should('not.be.disabled');
  });

  it('should display error message and handle edge case with empty password field', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Fill in valid email
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Leave password empty and click login
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response or validation
    cy.wait('@loginAttempt');

    // Assert appropriate error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Password is required');

    // Assert error state is applied to password field
    cy.get('[data-testid="password-input"]')
      .should('have.class', 'is-invalid');

    // Verify user can correct and retry
    cy.get('[data-testid="password-input"]').type('correctpassword');
    cy.get('[data-testid="password-input"]').should('not.have.class', 'is-invalid');
  });
});

