import { test, expect } from '@playwright/test';

test.describe('Authentication - Incorrect Password Error Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display error message when user enters incorrect password', async ({ page }) => {
    // Get email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    // Get password input using getByLabel
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword123');

    // Setup API interception before clicking
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Click login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Assert error message is visible and contains correct text
    const errorMessage = page.getByText('Invalid password');
    await expect(errorMessage).toBeVisible();

    // Assert error message has appropriate styling
    const errorContainer = page.locator('[data-testid="error-message"]');
    await expect(errorContainer).toContainText('Invalid password');

    // Assert password field is still visible and accessible
    await expect(passwordInput).toBeVisible();

    // Assert login button is still enabled for retry
    await expect(loginButton).not.toBeDisabled();
  });

  test('should display error message when password field is empty', async ({ page }) => {
    // Get email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    // Get password input using getByLabel (must use getByLabel/getByRole twice)
    const passwordInput = page.getByLabel('Password');

    // Setup API interception
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Click login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Assert validation error message is displayed
    const validationError = page.getByText('Password is required');
    await expect(validationError).toBeVisible();

    // Assert error styling is applied to password field
    await expect(passwordInput).toHaveAttribute('aria-invalid', 'true');

    // Verify user can correct the error and form recovers
    await passwordInput.fill('correctpassword123');
    await expect(passwordInput).not.toHaveAttribute('aria-invalid', 'true');

    // Assert submit button is now enabled
    await expect(loginButton).not.toBeDisabled();
  });
});

