describe('Password Reset Confirmation Message', () => {
  beforeEach(() => {
    cy.visit('/forgot-password');
  });

  it('should display confirmation message after successful password reset', () => {
    // Intercept the password reset API call
    cy.intercept('POST', '/api/auth/reset-password').as('resetPassword');

    // Fill in the email field
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Click the reset password button
    cy.get('[data-testid="reset-button"]').click();

    // Wait for the API call and mock successful response
    cy.wait('@resetPassword').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify confirmation message is visible
    cy.get('[data-testid="confirmation-message"]')
      .should('be.visible')
      .should('contain', 'Password reset successful');

    // Verify the message has the correct styling/type
    cy.get('[data-testid="confirmation-message"]')
      .should('have.class', 'success-alert');

    // Verify redirect link is visible
    cy.get('[data-testid="login-redirect-link"]')
      .should('be.visible')
      .should('contain', 'Return to Login');
  });

  it('should not display confirmation message when reset fails', () => {
    // Intercept the password reset API call with error response
    cy.intercept('POST', '/api/auth/reset-password', {
      statusCode: 400,
      body: { error: 'Invalid email address' }
    }).as('resetPasswordError');

    // Fill in invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');

    // Click the reset password button
    cy.get('[data-testid="reset-button"]').click();

    // Wait for the failed API call
    cy.wait('@resetPasswordError');

    // Verify success confirmation message does NOT appear
    cy.get('[data-testid="confirmation-message"]').should('not.exist');

    // Verify error message is displayed instead
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid email address');

    // Verify user is still on the reset page
    cy.url().should('include', '/forgot-password');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Password Reset Confirmation Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/forgot-password');
  });

  test('should display confirmation message after successful password reset', async ({ page }) => {
    // Intercept the password reset API call
    await page.route('**/api/auth/reset-password', (route) => {
      route.abort('failed');
    });

    // Setup successful API response
    await page.route('**/api/auth/reset-password', (route) => {
      route.continue();
      route.response().then((response) => {
        if (response.status() === 200) {
          return;
        }
      });
    });

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email address');
    await emailInput.fill('user@example.com');

    // Locate and click reset button using getByRole
    const resetButton = page.getByRole('button', { name: /reset password/i });
    await resetButton.click();

    // Wait for the confirmation message to appear
    const confirmationMessage = page.getByText('Password reset successful');
    await expect(confirmationMessage).toBeVisible();

    // Verify the message has correct styling
    const messageContainer = page.locator('[data-testid="confirmation-message"]');
    await expect(messageContainer).toHaveClass(/success-alert/);

    // Verify redirect link is visible using getByRole
    const loginLink = page.getByRole('link', { name: /return to login/i });
    await expect(loginLink).toBeVisible();
  });

  test('should not display confirmation message when reset fails', async ({ page }) => {
    // Mock failed API response
    await page.route('**/api/auth/reset-password', (route) => {
      route.abort('failed');
    });

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email address');
    await emailInput.fill('invalid-email');

    // Locate and click reset button using getByRole
    const resetButton = page.getByRole('button', { name: /reset password/i });
    await resetButton.click();

    // Wait briefly for potential error response
    await page.waitForTimeout(1000);

    // Verify success confirmation message does NOT appear
    const successMessage = page.getByText('Password reset successful');
    await expect(successMessage).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid email/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is still on the reset page
    await expect(page).toHaveURL(/forgot-password/);
  });
});

