describe('Login Form Empty Field Validation', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should prevent form submission when email and password fields are empty', () => {
    // Attempt to submit the form without entering any data
    cy.get('[data-testid="login-submit-btn"]').click();

    // Verify error messages appear for both fields
    cy.get('[data-testid="email-error-message"]')
      .should('be.visible')
      .should('contain', 'Email is required');

    cy.get('[data-testid="password-error-message"]')
      .should('be.visible')
      .should('contain', 'Password is required');

    // Verify the form was not submitted (no redirect or API call)
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should prevent form submission when only email field is filled and password is empty', () => {
    // Fill only the email field
    cy.get('[data-testid="email-input"]')
      .type('user@example.com');

    // Attempt to submit the form
    cy.get('[data-testid="login-submit-btn"]').click();

    // Verify error message appears only for password field
    cy.get('[data-testid="password-error-message"]')
      .should('be.visible')
      .should('contain', 'Password is required');

    // Verify error message does NOT appear for email field
    cy.get('[data-testid="email-error-message"]')
      .should('not.exist');

    // Verify the form was not submitted
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });
});

