        user: {
          id: 'user_123',
          email: 'testuser@gmail.com',
          name: 'Test User',
          picture: 'https://example.com/picture.jpg'
        }
      }
    }).as('googleAuth');

    cy.intercept('GET', '/api/user/profile', {
      statusCode: 200,
      body: {
        id: 'user_123',
        email: 'testuser@gmail.com',
        name: 'Test User',
        authenticated: true
      }
    }).as('userProfile');

    // Click Google Login button
    cy.get('[data-testid="google-login-btn"]').click();

    // Simulate Google OAuth popup window behavior
    cy.window().then((win) => {
      cy.stub(win, 'open').returns(win);
      cy.get('[data-testid="google-login-btn"]').click();
    });

    // Wait for OAuth callback
    cy.wait('@googleAuth');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');

    // Verify user profile is displayed
    cy.get('[data-testid="user-greeting"]').should('contain', 'Test User');
    cy.get('[data-testid="user-email"]').should('contain', 'testuser@gmail.com');

    // Verify authentication token is stored
    cy.window().then((win) => {
      expect(win.localStorage.getItem('auth_token')).to.equal('mock_jwt_token_12345');
    });

    // Verify logout button is available
    cy.get('[data-testid="logout-btn"]').should('be.visible');

    // Verify user profile API was called
    cy.wait('@userProfile');
  });

  it('should handle Google OAuth cancellation and network errors gracefully', () => {
    // Mock failed OAuth response
    cy.intercept('POST', '/api/auth/google/callback', {
      statusCode: 401,
      body: {
        success: false,
        error: 'oauth_cancelled',
        message: 'User cancelled Google OAuth flow'
      }
    }).as('googleAuthFailed');

