describe('Session Expiration after 30 Minutes of Inactivity', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('ValidPassword123!');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="dashboard-page"]').should('be.visible');
  });

  it('should expire session after 30 minutes of inactivity', () => {
    // Verify user is logged in and can access protected resources
    cy.get('[data-testid="user-profile-link"]').should('be.visible');
    cy.get('[data-testid="logout-button"]').should('be.visible');

    // Intercept the session check API call
    cy.intercept('GET', '/api/session/validate').as('validateSession');

    // Simulate 30 minutes of inactivity by advancing the clock
    cy.clock();
    cy.tick(30 * 60 * 1000);

    // Trigger a user action that should detect expired session
    cy.get('[data-testid="dashboard-refresh-button"]').click();
    cy.wait('@validateSession');

    // Verify that user is redirected to login page
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="session-expired-message"]').should('contain', 'Your session has expired');
    cy.get('[data-testid="user-profile-link"]').should('not.exist');
    cy.get('[data-testid="logout-button"]').should('not.exist');
  });

  it('should keep session alive when user is active within 30-minute window', () => {
    // Verify initial logged-in state
    cy.get('[data-testid="user-profile-link"]').should('be.visible');
    cy.get('[data-testid="dashboard-page"]').should('be.visible');

    // Intercept session validation endpoints
    cy.intercept('POST', '/api/session/refresh').as('refreshSession');
    cy.intercept('GET', '/api/session/validate').as('validateSession');

    // Simulate clock advancement and user activity
    cy.clock();

    // Advance 15 minutes
    cy.tick(15 * 60 * 1000);
    cy.get('[data-testid="dashboard-content"]').click();
    cy.wait('@refreshSession');

    // Advance another 10 minutes (total 25 minutes)
    cy.tick(10 * 60 * 1000);
    cy.get('[data-testid="sidebar-menu"]').click();
    cy.wait('@refreshSession');

    // Advance 4 more minutes (total 29 minutes - within the 30-minute window)
    cy.tick(4 * 60 * 1000);
    cy.get('[data-testid="settings-button"]').click();
    cy.wait('@refreshSession');

    // Verify user is still logged in and session is valid
    cy.get('[data-testid="user-profile-link"]').should('be.visible');
    cy.get('[data-testid="logout-button"]').should('be.visible');
    cy.get('[data-testid="session-expired-message"]').should('not.exist');
    cy.get('[data-testid="dashboard-page"]').should('be.visible');
  });
});

