describe('Username Pre-fill on Return Login', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display pre-filled username for returning user with valid stored credentials', () => {
    // Set up localStorage to simulate a previous login
    cy.window().then((win) => {
      win.localStorage.setItem('lastLoggedInUser', 'johndoe@example.com');
    });

    // Reload the page to trigger the pre-fill logic
    cy.reload();

    // Verify the username input field is pre-filled
    cy.get('[data-testid="username-input"]').should('have.value', 'johndoe@example.com');

    // Verify the input field is visible
    cy.get('[data-testid="username-input"]').should('be.visible');

    // Complete login flow
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="login-button"]').click();

    // Mock the login API endpoint
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');

    // Verify successful login redirect
    cy.url().should('include', '/dashboard');
  });

  it('should not pre-fill username when no previous login data exists or localStorage is cleared', () => {
    // Ensure localStorage is empty
    cy.window().then((win) => {
      win.localStorage.clear();
    });

    cy.reload();

    // Verify the username input field is empty
    cy.get('[data-testid="username-input"]').should('have.value', '');

    // Verify placeholder text is displayed instead
    cy.get('[data-testid="username-input"]').should('have.attr', 'placeholder', 'Enter your email');

    // Attempt to submit without entering username
    cy.get('[data-testid="password-input"]').type('SomePassword');
    cy.get('[data-testid="login-button"]').click();

    // Mock the login API to expect validation error
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 400,
      body: { error: 'Username is required' }
    }).as('loginValidationError');

    cy.wait('@loginValidationError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Username is required');

    // Verify user remains on login page
    cy.url().should('include', '/login');
  });
});

