    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="email-input"]').should('have.value', 'user@example.com');

    // Tab to password input
    cy.get('[data-testid="email-input"]').tab();
    cy.get('[data-testid="password-input"]').should('have.focus');

    // Type password
    cy.get('[data-testid="password-input"]').type('ValidPassword123');
    cy.get('[data-testid="password-input"]').should('have.value', 'ValidPassword123');

    // Tab to submit button
    cy.get('[data-testid="password-input"]').tab();
    cy.get('[data-testid="submit-button"]').should('have.focus');

    // Intercept login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

