  });

  it('should accept only numeric input and display formatted phone number', () => {
    // Get the phone number input field
    cy.get('[data-testid="phone-number-input"]').should('be.visible');

    // Type valid numeric phone number
    cy.get('[data-testid="phone-number-input"]').type('5551234567');

    // Verify the input contains only the numeric values
    cy.get('[data-testid="phone-number-input"]').should('have.value', '5551234567');

