describe('Date Picker - Past Date Prevention for Future Bookings', () => {
  beforeEach(() => {
    cy.visit('/booking');
  });

  it('should allow selecting a future date and successfully submit the booking form', () => {
    // Get today's date and calculate a future date (7 days from now)
    const today = new Date();
    const futureDate = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
    const formattedFutureDate = futureDate.toISOString().split('T')[0];

    // Intercept the booking API call
    cy.intercept('POST', '/api/bookings').as('submitBooking');

    // Click on the date picker input
    cy.get('[data-testid="date-picker-input"]').click();

    // Select the future date from the calendar
    cy.get('[data-testid="date-picker-calendar"]').should('be.visible');
    cy.get(`[data-testid="calendar-day-${formattedFutureDate}"]`).click();

    // Verify the selected date is displayed in the input
    cy.get('[data-testid="date-picker-input"]').should('have.value', formattedFutureDate);

    // Fill in other required booking fields
    cy.get('[data-testid="guest-name-input"]').type('John Doe');
    cy.get('[data-testid="guest-email-input"]').type('john@example.com');
    cy.get('[data-testid="booking-description"]').type('Standard booking');

    // Submit the form
    cy.get('[data-testid="submit-booking-btn"]').click();

    // Verify the API call was made and succeeded
    cy.wait('@submitBooking').its('response.statusCode').should('eq', 201);

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Booking confirmed');
  });

  it('should prevent selecting past dates and display validation error', () => {
    // Get today's date and calculate a past date (3 days ago)
    const today = new Date();
    const pastDate = new Date(today.getTime() - 3 * 24 * 60 * 60 * 1000);
    const formattedPastDate = pastDate.toISOString().split('T')[0];

    // Click on the date picker input
    cy.get('[data-testid="date-picker-input"]').click();

    // Wait for calendar to appear
    cy.get('[data-testid="date-picker-calendar"]').should('be.visible');

    // Attempt to click on a past date (should be disabled)
    cy.get(`[data-testid="calendar-day-${formattedPastDate}"]`).should('have.attr', 'disabled');

    // Verify that past date button is not clickable and has disabled styling
    cy.get(`[data-testid="calendar-day-${formattedPastDate}"]`).should('have.class', 'disabled-date');

    // Try to manually type a past date into the input field
    cy.get('[data-testid="date-picker-input"]').type(formattedPastDate);

    // Fill in other booking fields to attempt submission
    cy.get('[data-testid="guest-name-input"]').type('Jane Doe');
    cy.get('[data-testid="guest-email-input"]').type('jane@example.com');

    // Click submit
    cy.get('[data-testid="submit-booking-btn"]').click();

    // Verify validation error message appears
    cy.get('[data-testid="date-validation-error"]').should('be.visible').should('contain', 'Please select a future date');

    // Verify form was not submitted
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});

