describe('ZIP Code Auto-Format Field', () => {
  beforeEach(() => {
    cy.visit('/form/address');
  });

  it('should auto-format ZIP code as user types (happy path)', () => {
    // Intercept any API calls for form submission
    cy.intercept('POST', '/api/address/validate').as('validateAddress');

    // Get the ZIP code input field
    cy.get('[data-testid="zip-code-input"]').should('be.visible');

    // Type ZIP code without dashes
    cy.get('[data-testid="zip-code-input"]').type('12345');

    // Verify first part is displayed
    cy.get('[data-testid="zip-code-input"]').should('have.value', '12345');

    // Continue typing to trigger auto-format to XXXXX-XXXX pattern
    cy.get('[data-testid="zip-code-input"]').type('6789');

    // Verify auto-formatted value with dash
    cy.get('[data-testid="zip-code-input"]').should('have.value', '12345-6789');

    // Verify format helper text appears
    cy.get('[data-testid="zip-format-helper"]').should('be.visible').should('contain', 'XXXXX-XXXX');

    // Submit form to validate
    cy.get('[data-testid="submit-button"]').click();

    // Wait for validation API
    cy.wait('@validateAddress').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Address validated successfully');
  });

  it('should handle invalid ZIP code input (negative/edge case)', () => {
    cy.intercept('POST', '/api/address/validate').as('validateAddress');

    cy.get('[data-testid="zip-code-input"]').should('be.visible');

    // Type only letters (invalid)
    cy.get('[data-testid="zip-code-input"]').type('ABCDE');

    // Verify no formatting applied and field remains empty or shows only numbers
    cy.get('[data-testid="zip-code-input"]').should('have.value', '');

    // Try typing special characters
    cy.get('[data-testid="zip-code-input"]').type('!@#$%');

    // Verify special characters are rejected
    cy.get('[data-testid="zip-code-input"]').should('have.value', '');

    // Type incomplete ZIP code (less than 5 digits)
    cy.get('[data-testid="zip-code-input"]').type('123');

    // Verify no dash is added yet
    cy.get('[data-testid="zip-code-input"]').should('have.value', '123');

    // Verify error message for incomplete input
    cy.get('[data-testid="zip-error-message"]').should('be.visible').should('contain', 'ZIP code must be at least 5 digits');

    // Try to submit with incomplete ZIP
    cy.get('[data-testid="submit-button"]').click();

    // Verify form does not submit and error persists
    cy.get('[data-testid="zip-error-message"]').should('be.visible').should('contain', 'ZIP code must be at least 5 digits');

    // Verify API was not called
    cy.get('@validateAddress').should('not.exist');
  });
});

