    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');
  });

  it('should reject files larger than 5MB with error message', () => {
    // Create a large test file (8MB)
    const largeFileContent = new Uint8Array(8 * 1024 * 1024);
    cy.get('[data-testid="file-input"]').selectFile({
      contents: largeFileContent,
      fileName: 'large-document.pdf',
      mimeType: 'application/pdf',
      lastModified: Date.now()
    });

    // Verify file is selected
    cy.get('[data-testid="file-name-display"]').should('contain', 'large-document.pdf');

    // Error message should appear immediately
    cy.get('[data-testid="error-message"]').should('be.visible');
