    cy.wait('@saveDraft', { timeout: 35000 });

    cy.wait('@saveDraft').then((interception) => {
      expect(interception.request.body.message).to.equal('Updated message');
    });

    // Verify draft timestamp is updated
    cy.get('[data-testid="draft-timestamp"]').should('contain', 'just now');
  });

  it('should handle auto-save failures and display error message', () => {
