    await messageInput.fill('Updated message');

    const savePromise2 = page.waitForResponse((response) =>
      response.url().includes('/api/drafts/save') && response.status() === 200
    );

    await Promise.race([
      savePromise2,
      new Promise((resolve) => setTimeout(resolve, 35000)),
    ]);

    // Verify updated notification
    await expect(draftNotification).toBeVisible();

    // Verify message was saved with new content
    await expect(messageInput).toHaveValue('Updated message');
  });

  test('should handle auto-save failures and display error message', async ({ page }) => {
