    cy.get('[data-testid="last-name-input"]').should('have.value', 'Smith');

    // Try to click on a previous step directly (edge case)
    cy.get('[data-testid="progress-step-1"]').click();
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'active');
    cy.get('[data-testid="progress-step-2"]').should('not.have.class', 'active');
  });
});

