import { test, expect } from '@playwright/test';

test.describe('Form Submission - Confirmation Email', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should send confirmation email after successful form submission', async ({ page }) => {
    // Set up API interception for form submission
    await page.route('**/api/contact-form', route => {
      route.continue();
    });

    // Set up API interception for email confirmation
    let emailSendCalled = false;
    await page.route('**/api/email/send-confirmation', route => {
      emailSendCalled = true;
      route.abort();
      route.continue();
    });

    // Fill in form using getByLabel and getByRole
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    const subjectInput = page.getByLabel('Subject');
    await subjectInput.fill('Test Inquiry');

    // Fill message textarea
    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message for form submission.');

    // Submit the form using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for success message to appear
    const successMessage = page.getByText(/confirmation email has been sent/i);
    await expect(successMessage).toBeVisible();

    // Verify email input retains value for confirmation display
    await expect(emailInput).toHaveValue('john.doe@example.com');
  });

  test('should display error when email field is invalid or empty', async ({ page }) => {
    // Fill in form fields
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    // Leave email empty - edge case
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeEmpty();

    const subjectInput = page.getByLabel('Subject');
    await subjectInput.fill('Support Request');

    // Fill message
    const messageInput = page.getByLabel('Message');
    await messageInput.fill('Please help me with this issue.');

    // Try to submit
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify email validation error appears
    const errorMessage = page.getByText(/email is required|please enter a valid email/i);
    await expect(errorMessage).toBeVisible();

    // Verify form was not submitted - success message should not exist
    const successMessage = page.getByText(/confirmation email has been sent/i);
    await expect(successMessage).not.toBeVisible();

    // Verify submit button is still enabled for retry
    await expect(submitButton).toBeEnabled();
  });
});

