describe('Internal Links Navigation - Same Tab Opening', () => {
  beforeEach(() => {
    cy.visit('/pages/home');
  });

  it('should open internal links in the same tab without target="_blank"', () => {
    // Intercept navigation to verify same-tab behavior
    cy.intercept('GET', '/pages/**').as('pageLoad');

    // Verify initial page is visible
    cy.get('[data-testid="home-heading"]').should('be.visible');
    cy.get('[data-testid="home-heading"]').should('contain', 'Home');

    // Find and click an internal navigation link
    cy.get('[data-testid="nav-about-link"]').should('be.visible');
    cy.get('[data-testid="nav-about-link"]').should('have.attr', 'href', '/pages/about');
    cy.get('[data-testid="nav-about-link"]').should('not.have.attr', 'target', '_blank');

    cy.get('[data-testid="nav-about-link"]').click();

    // Wait for page load and verify navigation occurred in same tab
    cy.wait('@pageLoad');
    cy.url().should('include', '/pages/about');
    cy.get('[data-testid="about-heading"]').should('be.visible');
    cy.get('[data-testid="about-heading"]').should('contain', 'About');

    // Verify browser history allows back navigation (same tab indicator)
    cy.go('back');
    cy.url().should('include', '/pages/home');
    cy.get('[data-testid="home-heading"]').should('be.visible');
  });

  it('should not open external links in same tab and handle edge case of misconfigured internal links', () => {
    // Verify home page loaded
    cy.get('[data-testid="home-heading"]').should('be.visible');

    // Test external link has proper target="_blank" attribute
    cy.get('[data-testid="external-link"]').should('exist');
    cy.get('[data-testid="external-link"]').should('have.attr', 'target', '_blank');
    cy.get('[data-testid="external-link"]').should('have.attr', 'href').and('include', 'https://');

    // Test internal link without href (edge case - broken link)
    cy.get('[data-testid="broken-internal-link"]').should('exist');
    cy.get('[data-testid="broken-internal-link"]').should('not.have.attr', 'href');

    // Click broken link and verify page doesn't navigate
    cy.get('[data-testid="broken-internal-link"]').click();
    cy.url().should('include', '/pages/home');
    cy.get('[data-testid="home-heading"]').should('be.visible');

    // Test relative internal link (e.g., '../contact')
    cy.get('[data-testid="relative-internal-link"]').should('exist');
    cy.get('[data-testid="relative-internal-link"]').should('not.have.attr', 'target');
    cy.get('[data-testid="relative-internal-link"]').click();

    // Verify same tab behavior with relative paths
    cy.url().should('not.include', '_blank');
  });
});

