describe('Browser Back Button Navigation - App State Preservation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should preserve app state when using browser back button after navigation', () => {
    // Navigate to form page and fill in data
    cy.get('[data-testid="navigate-to-form"]').click();
    cy.get('[data-testid="form-input-name"]').type('John Doe');
    cy.get('[data-testid="form-input-email"]').type('john@example.com');
    cy.get('[data-testid="form-dropdown"]').click();
    cy.get('[data-testid="dropdown-option-premium"]').click();

    // Verify form data is visible
    cy.get('[data-testid="form-input-name"]').should('have.value', 'John Doe');
    cy.get('[data-testid="form-input-email"]').should('have.value', 'john@example.com');
    cy.get('[data-testid="form-dropdown"]').should('contain', 'Premium');

    // Navigate to another page
    cy.get('[data-testid="navigate-to-profile"]').click();
    cy.get('[data-testid="profile-header"]').should('be.visible');
    cy.get('[data-testid="profile-name"]').should('contain', 'John Doe');

    // Use browser back button
    cy.go('back');

    // Verify form state is preserved
    cy.get('[data-testid="form-input-name"]').should('have.value', 'John Doe');
    cy.get('[data-testid="form-input-email"]').should('have.value', 'john@example.com');
    cy.get('[data-testid="form-dropdown"]').should('contain', 'Premium');
    cy.get('[data-testid="form-state-preserved"]').should('be.visible');
  });

  it('should handle back button navigation with API calls without data loss or duplicate requests', () => {
    // Mock API endpoint
    cy.intercept('GET', '/api/users/list').as('getUsersList');
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Navigate and trigger API call
    cy.get('[data-testid="navigate-to-users"]').click();
    cy.wait('@getUsersList');
    cy.get('[data-testid="users-table"]').should('be.visible');
    cy.get('[data-testid="user-row-1"]').should('contain', 'Alice');

    // Navigate to another section
    cy.get('[data-testid="navigate-to-settings"]').click();
    cy.get('[data-testid="settings-panel"]').should('be.visible');

    // Use back button twice
    cy.go('back');
    cy.wait('@getUsersList');
    cy.get('[data-testid="users-table"]').should('be.visible');
    cy.get('[data-testid="user-row-1"]').should('contain', 'Alice');

    // Verify no duplicate API calls were made
    cy.get('@getUsersList.all').should('have.length', 2);

    // Navigate back to settings and then forward
    cy.go('back');
    cy.get('[data-testid="settings-panel"]').should('be.visible');

    cy.go('forward');
    cy.get('[data-testid="users-table"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('not.exist');
