describe('Mobile Hamburger Menu Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should open and close hamburger menu on user interaction', () => {
    // Verify hamburger menu button is visible on mobile viewport
    cy.get('[data-testid="hamburger-menu-button"]').should('be.visible');

    // Verify menu is closed initially
    cy.get('[data-testid="mobile-nav-menu"]').should('not.be.visible');

    // Click hamburger button to open menu
    cy.get('[data-testid="hamburger-menu-button"]').click();

    // Verify menu is now visible
    cy.get('[data-testid="mobile-nav-menu"]').should('be.visible');

    // Verify menu contains expected navigation links
    cy.get('[data-testid="mobile-nav-menu"]').should('contain', 'Home');
    cy.get('[data-testid="mobile-nav-menu"]').should('contain', 'About');
    cy.get('[data-testid="mobile-nav-menu"]').should('contain', 'Contact');

    // Click hamburger button again to close menu
    cy.get('[data-testid="hamburger-menu-button"]').click();

    // Verify menu is closed
    cy.get('[data-testid="mobile-nav-menu"]').should('not.be.visible');
  });

  it('should close menu when clicking outside or on a menu link', () => {
    // Open the hamburger menu
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-nav-menu"]').should('be.visible');

    // Click on a menu link (e.g., Home)
    cy.get('[data-testid="mobile-nav-link-home"]').click();

    // Verify menu closes after navigation link click
    cy.get('[data-testid="mobile-nav-menu"]').should('not.be.visible');

    // Verify navigation occurred
    cy.url().should('include', '/');

    // Open menu again to test closing by clicking outside
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-nav-menu"]').should('be.visible');

    // Click outside the menu (on the page background)
    cy.get('[data-testid="main-content"]').click({ force: true });

    // Verify menu closes when clicking outside
    cy.get('[data-testid="mobile-nav-menu"]').should('not.be.visible');
  });
});

