describe('Sticky Header Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should keep header visible when scrolling down the page', () => {
    // Verify header is visible initially
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'sticky');

    // Verify header contains navigation links
    cy.get('[data-testid="nav-home"]').should('be.visible');
    cy.get('[data-testid="nav-about"]').should('be.visible');
    cy.get('[data-testid="nav-contact"]').should('be.visible');

    // Scroll down the page
    cy.scrollTo('bottom');

    // Header should still be visible at the top
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'sticky');

    // Navigation links should remain accessible
    cy.get('[data-testid="nav-home"]').should('be.visible');
    cy.get('[data-testid="nav-about"]').should('be.visible');

    // Verify header is still in viewport
    cy.get('[data-testid="header"]').should('have.css', 'top', '0px');

    // Click navigation link while scrolled
    cy.get('[data-testid="nav-about"]').click();
    cy.url().should('include', '/about');

    // Header should remain sticky after navigation
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'sticky');
  });

  it('should handle edge case where header z-index prevents content interaction', () => {
    // Scroll to ensure header is visible
    cy.scrollTo(0, 100);

    // Get header and verify z-index is set appropriately
    cy.get('[data-testid="header"]').should('have.css', 'z-index').and('not.equal', 'auto');

    // Verify content below header is still clickable (header should not block it)
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="hero-button"]').should('be.visible').click();

    // Verify button interaction was successful
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Success');

    // Test that header doesn't overlap critical content
    cy.get('[data-testid="header"]').then(($header) => {
      cy.get('[data-testid="main-content"]').then(($content) => {
        const headerHeight = $header.outerHeight();
        const contentTop = $content.offset().top;
        expect(contentTop).to.be.greaterThan(headerHeight);
      });
    });

    // Scroll back to top and verify header position
    cy.scrollTo('top');
    cy.get('[data-testid="header"]').should('have.css', 'top', '0px');
    cy.get('[data-testid="header"]').should('be.visible');
  });
});

