    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

    // Verify header contains navigation links with proper roles
    const homeLink = page.getByRole('link', { name: /home/i });
    const aboutLink = page.getByRole('link', { name: /about/i });
    const contactLink = page.getByRole('link', { name: /contact/i });

    await expect(homeLink).toBeVisible();
    await expect(aboutLink).toBeVisible();
    await expect(contactLink).toBeVisible();

    // Check header has sticky positioning
    const headerStyles = await header.evaluate((el) => window.getComputedStyle(el).position);
    expect(headerStyles).toBe('sticky');

    // Scroll down the page
    await page.evaluate(() => window.scrollBy(0, 500));

    // Header should still be visible after scrolling
    await expect(header).toBeVisible();

    // Navigation links should remain accessible
    await expect(homeLink).toBeVisible();
    await expect(aboutLink).toBeVisible();

    // Verify header position is at top
    const topPos = await header.evaluate((el) => window.getComputedStyle(el).top);
    expect(topPos).toBe('0px');

    // Click navigation link while scrolled
    await aboutLink.click();
    await expect(page).toHaveURL(/\/about/);

    // Header should remain sticky after navigation
    await expect(header).toBeVisible();
    const afterNavStyles = await header.evaluate((el) => window.getComputedStyle(el).position);
    expect(afterNavStyles).toBe('sticky');
  });

  test('should handle edge case where header z-index prevents content interaction', async ({ page }) => {
    // Scroll to middle of page
    await page.evaluate(() => window.scrollBy(0, 100));

    // Get header and main content
    const header = page.getByRole('banner');
    const mainContent = page.locator('[data-testid="main-content"]');
    const heroButton = page.getByRole('button', { name: /call to action/i });

    // Verify header has appropriate z-index
    const zIndex = await header.evaluate((el) => window.getComputedStyle(el).zIndex);
    expect(zIndex).not.toBe('auto');

    // Verify content is visible and clickable
    await expect(mainContent).toBeVisible();
    await expect(heroButton).toBeVisible();

    // Click button and verify interaction
    await heroButton.click();

    const successMsg = page.getByText(/success/i);
    await expect(successMsg).toBeVisible();

    // Verify header doesn't overlap content by checking vertical positions
    const headerBox = await header.boundingBox();
    const contentBox = await mainContent.boundingBox();

    if (headerBox && contentBox) {
      const headerBottom = headerBox.y + headerBox.height;
      expect(contentBox.y).toBeGreaterThanOrEqual(headerBottom - 5); // 5px tolerance
    }

    // Scroll back to top
    await page.evaluate(() => window.scrollTo(0, 0));

    // Verify header is at top
    await expect(header).toBeVisible();
    const topPos = await header.evaluate((el) => window.getComputedStyle(el).top);
    expect(topPos).toBe('0px');
  });
});

