describe('Page Title Update on Navigation Between Sections', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should update page title when navigating between sections - happy path', () => {
    // Verify initial page title
    cy.title().should('equal', 'Dashboard');

    // Intercept API call for section data
    cy.intercept('GET', '/api/sections/profile').as('getProfileSection');

    // Navigate to Profile section
    cy.get('[data-testid="nav-profile-link"]').click();
    cy.wait('@getProfileSection');

    // Verify page title updates to Profile
    cy.title().should('equal', 'Profile');
    cy.get('[data-testid="page-title"]').should('contain', 'Profile');

    // Intercept API call for reports section
    cy.intercept('GET', '/api/sections/reports').as('getReportsSection');

    // Navigate to Reports section
    cy.get('[data-testid="nav-reports-link"]').click();
    cy.wait('@getReportsSection');

    // Verify page title updates to Reports
    cy.title().should('equal', 'Reports');
    cy.get('[data-testid="page-title"]').should('contain', 'Reports');

    // Navigate back to Dashboard
    cy.intercept('GET', '/api/sections/dashboard').as('getDashboardSection');
    cy.get('[data-testid="nav-dashboard-link"]').click();
    cy.wait('@getDashboardSection');

    // Verify page title returns to Dashboard
    cy.title().should('equal', 'Dashboard');
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');
  });

  it('should handle navigation with missing section data - negative case', () => {
    // Intercept API to simulate error response
    cy.intercept('GET', '/api/sections/settings', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('getSettingsError');

    // Attempt to navigate to Settings
    cy.get('[data-testid="nav-settings-link"]').click();
    cy.wait('@getSettingsError');

    // Verify page title does NOT update and error is displayed
    cy.title().should('equal', 'Dashboard');
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Failed to load section');

    // Verify user remains on Dashboard with correct title
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');
  });
});

