describe('Pagination Controls - Load Correct Page of Results', () => {
  beforeEach(() => {
    cy.visit('/results');
    cy.intercept('GET', '/api/results?page=1&limit=10').as('getPage1');
    cy.wait('@getPage1');
  });

  it('Happy path: User navigates through pages and loads correct results', () => {
    // Verify page 1 is loaded with initial results
    cy.get('[data-testid="result-item"]').should('have.length', 10);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Result 1');
    cy.get('[data-testid="page-info"]').should('contain', 'Page 1 of 5');

    // Navigate to page 2
    cy.intercept('GET', '/api/results?page=2&limit=10').as('getPage2');
    cy.get('[data-testid="next-page-btn"]').click();
    cy.wait('@getPage2');

    // Verify page 2 results are loaded
    cy.get('[data-testid="result-item"]').should('have.length', 10);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Result 11');
    cy.get('[data-testid="page-info"]').should('contain', 'Page 2 of 5');
    cy.get('[data-testid="prev-page-btn"]').should('not.be.disabled');
    cy.get('[data-testid="next-page-btn"]').should('not.be.disabled');

    // Navigate to page 5 (last page)
    cy.intercept('GET', '/api/results?page=5&limit=10').as('getPage5');
    cy.get('[data-testid="page-input"]').clear().type('5');
    cy.get('[data-testid="go-btn"]').click();
    cy.wait('@getPage5');

    // Verify page 5 results with fewer items
    cy.get('[data-testid="result-item"]').should('have.length', 5);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Result 41');
    cy.get('[data-testid="page-info"]').should('contain', 'Page 5 of 5');
    cy.get('[data-testid="next-page-btn"]').should('be.disabled');
  });

  it('Negative/Edge case: Invalid page input and boundary conditions', () => {
    // Test invalid page number (exceeds max)
    cy.get('[data-testid="page-input"]').clear().type('10');
    cy.get('[data-testid="go-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Page does not exist');
    cy.get('[data-testid="result-item"]').should('not.exist');

    // Test negative page number
    cy.get('[data-testid="page-input"]').clear().type('-1');
    cy.get('[data-testid="go-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid page number');

    // Test non-numeric input
    cy.get('[data-testid="page-input"]').clear().type('abc');
    cy.get('[data-testid="go-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'must be a number');

    // Verify page 1 button is disabled when on page 1
    cy.intercept('GET', '/api/results?page=1&limit=10').as('resetPage1');
    cy.get('[data-testid="first-page-btn"]').click();
    cy.wait('@resetPage1');
    cy.get('[data-testid="prev-page-btn"]').should('be.disabled');
    cy.get('[data-testid="first-page-btn"]').should('be.disabled');
  });
});

