describe('Retry Button on Network Timeout', () => {
  beforeEach(() => {
    cy.visit('/network-request-page');
  });

  it('should display retry button and successfully retry after network timeout', () => {
    // Intercept the API call and simulate a timeout on first attempt
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(15000); // Simulate timeout
      });
    }).as('firstRequest');

    // Trigger the network request
    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@firstRequest');

    // Verify timeout error message and retry button are visible
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Request timed out');
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Setup successful response for retry
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'Success', timestamp: new Date().toISOString() }
    }).as('retryRequest');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@retryRequest');

    // Verify successful response is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Data loaded successfully');
    cy.get('[data-testid="data-content"]').should('contain', 'Success');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should handle retry button interaction when user clicks retry multiple times during failed request', () => {
    // Intercept API and simulate timeout
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(15000);
      });
    }).as('failedRequest');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@failedRequest');

    // Verify retry button appears
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Simulate another timeout on first retry attempt
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(15000);
      });
    }).as('secondFailedRequest');

    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@secondFailedRequest');

    // Verify retry button is still available and error persists
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Request timed out');
    cy.get('[data-testid="retry-attempts-counter"]').should('contain', '2');
  });
});

