describe('Optimistic UI Updates - Like Post Feature', () => {
  beforeEach(() => {
    cy.visit('/posts');
    cy.intercept('POST', '/api/posts/*/likes', {
      statusCode: 200,
      body: { success: true, likes: 42 }
    }).as('likePost');
    cy.intercept('GET', '/api/posts', {
      statusCode: 200,
      body: [
        {
          id: 1,
          title: 'Test Post',
          content: 'This is a test post',
          likes: 41,
          liked: false
        }
      ]
    }).as('getPosts');
    cy.wait('@getPosts');
  });

  it('should show optimistic UI update when liking a post and confirm with API response', () => {
    cy.get('[data-testid="post-1"]').should('be.visible');
    cy.get('[data-testid="like-button-1"]').should('contain', '41');
    cy.get('[data-testid="like-button-1"]').should('not.have.class', 'liked');

    // User clicks like button - optimistic update should happen immediately
    cy.get('[data-testid="like-button-1"]').click();

    // Verify optimistic UI update happens before API response
    cy.get('[data-testid="like-button-1"]').should('contain', '42');
    cy.get('[data-testid="like-button-1"]').should('have.class', 'liked');
    cy.get('[data-testid="like-icon-1"]').should('have.attr', 'aria-label', 'Unlike');

    // Wait for API confirmation
