    cy.get('[data-testid="like-button-1"]').should('have.class', 'liked');
  });

  it('should rollback optimistic update if API request fails', () => {
    cy.intercept('POST', '/api/posts/*/likes', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('likePostFail');

    cy.get('[data-testid="like-button-1"]').should('contain', '41');

    // User clicks like button - optimistic update shows immediately
    cy.get('[data-testid="like-button-1"]').click();
