describe('Stale Data Invalidation After Form Submission', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should invalidate stale data after successful form submission', () => {
    // Intercept initial data fetch
    cy.intercept('GET', '/api/user-data').as('initialDataFetch');
    cy.wait('@initialDataFetch');

    // Verify initial stale data is displayed
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john@example.com');

    // Fill form with new data
    cy.get('[data-testid="form-name-input"]').type('Jane Smith');
    cy.get('[data-testid="form-email-input"]').clear().type('jane@example.com');

    // Intercept form submission
    cy.intercept('POST', '/api/update-user').as('formSubmit');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for successful submission
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Intercept refreshed data endpoint
    cy.intercept('GET', '/api/user-data').as('refreshedDataFetch');
    cy.wait('@refreshedDataFetch');

    // Verify stale data has been invalidated and updated
    cy.get('[data-testid="user-name"]').should('contain', 'Jane Smith');
    cy.get('[data-testid="user-email"]').should('contain', 'jane@example.com');
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Data updated successfully');
  });

  it('should not invalidate stale data when form submission fails', () => {
    // Intercept initial data fetch
    cy.intercept('GET', '/api/user-data').as('initialDataFetch');
    cy.wait('@initialDataFetch');

    // Verify initial stale data is displayed
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john@example.com');

    // Fill form with invalid data
    cy.get('[data-testid="form-name-input"]').type('');
    cy.get('[data-testid="form-email-input"]').clear().type('invalid-email');

    // Intercept failed form submission
    cy.intercept('POST', '/api/update-user', { statusCode: 400, body: { error: 'Validation failed' } }).as('failedSubmit');

    // Attempt to submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for failed submission
    cy.wait('@failedSubmit');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Validation failed');

    // Verify stale data remains unchanged (NOT invalidated)
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john@example.com');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});

