describe('Search Results with Debounced Updates', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.intercept('GET', '/api/search?q=*').as('searchQuery');
  });

  it('should debounce search queries by 300ms and update results as user types', () => {
    // Arrange
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Act - Type first character
    cy.get('[data-testid="search-input"]').type('j');
    cy.wait(150);

    // Assert - No API call yet (within debounce window)
    cy.get('@searchQuery').then((interception) => {
      expect(interception).to.be.null;
    });

    // Act - Type second character (still within debounce)
    cy.get('[data-testid="search-input"]').type('a');
    cy.wait(150);

    // Act - Type third character and wait for debounce to complete
    cy.get('[data-testid="search-input"]').type('v');
    cy.wait(300);

    // Assert - API call triggered with debounced value
    cy.wait('@searchQuery').then((interception) => {
      expect(interception.request.url).to.include('q=jav');
    });

    // Assert - Results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Java');
  });

  it('should handle empty search input and show no results message', () => {
    // Arrange
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Act - Type and then clear the input
    cy.get('[data-testid="search-input"]').type('test').clear();
    cy.wait(400);

    // Assert - API call triggered with empty query
    cy.wait('@searchQuery').then((interception) => {
      expect(interception.request.url).to.include('q=');
    });

    // Assert - Empty state message is shown
    cy.get('[data-testid="empty-state"]').should('be.visible');
    cy.get('[data-testid="empty-state"]').should('contain', 'No results found');
    cy.get('[data-testid="search-results"]').should('not.exist');
    cy.get('[data-testid="result-item"]').should('not.exist');
  });
});

