describe('Duplicate Record Functionality', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully duplicate an existing record with one click', () => {
    // Intercept the GET request to load records
    cy.intercept('GET', '/api/records').as('getRecords');
    cy.wait('@getRecords');

    // Find and verify the first record is visible
    cy.get('[data-testid="record-item-1"]').should('be.visible');
    cy.get('[data-testid="record-name-1"]').should('contain', 'Sample Record');

    // Click the duplicate button on the first record
    cy.get('[data-testid="duplicate-btn-1"]').click();

    // Intercept the POST request for duplication
    cy.intercept('POST', '/api/records/1/duplicate').as('duplicateRecord');
    cy.wait('@duplicateRecord');

    // Verify success notification appears
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Record duplicated successfully');

    // Verify the new duplicated record appears in the list
    cy.get('[data-testid="record-item-2"]').should('be.visible');
    cy.get('[data-testid="record-name-2"]').should('contain', 'Sample Record (Copy)');

    // Verify the duplicated record has the same content as original
    cy.get('[data-testid="record-description-1"]').then(($original) => {
      const originalText = $original.text();
      cy.get('[data-testid="record-description-2"]').should('contain', originalText);
    });
  });

  it('should show error message when duplicating a deleted record', () => {
    // Intercept the GET request to load records
    cy.intercept('GET', '/api/records').as('getRecords');
    cy.wait('@getRecords');

    // Attempt to duplicate a non-existent record (simulate deleted record)
    cy.intercept('POST', '/api/records/999/duplicate', {
      statusCode: 404,
      body: { error: 'Record not found' }
    }).as('duplicateDeletedRecord');

    // Try to trigger duplicate on non-existent record
    cy.get('[data-testid="duplicate-btn-999"]').should('not.exist');

    // Alternative: attempt duplication via URL or button that exists but record is deleted
    cy.intercept('POST', '/api/records/*/duplicate').as('duplicateFail');
    cy.get('[data-testid="record-item-1"]').should('be.visible');
    cy.get('[data-testid="duplicate-btn-1"]').click();

    // Simulate server error response
