import { test, expect } from '@playwright/test';

test.describe('Duplicate Record Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully duplicate an existing record with one click', async ({ page }) => {
    // Intercept GET request to load records
    await page.waitForResponse(response => response.url().includes('/api/records') && response.status() === 200);

    // Locate and verify the first record is visible using getByRole
    const recordItem = page.getByRole('row', { name: /Sample Record/ });
    await expect(recordItem).toBeVisible();

    // Get the duplicate button using getByRole
    const duplicateButton = page.getByRole('button', { name: /Duplicate/i });
    await expect(duplicateButton).toBeVisible();

    // Set up intercept for duplication POST request
    const duplicatePromise = page.waitForResponse(response => 
      response.url().includes('/api/records') && response.request().method() === 'POST'
    );

    // Click the duplicate button
    await duplicateButton.click();

    // Wait for the POST response
    const duplicateResponse = await duplicatePromise;
    expect(duplicateResponse.status()).toBe(201);

    // Verify success notification appears using getByText
    const successToast = page.getByText(/Record duplicated successfully/);
    await expect(successToast).toBeVisible();

    // Verify the duplicated record appears in the list
    const duplicatedRecord = page.getByRole('row', { name: /Sample Record \(Copy\)/ });
    await expect(duplicatedRecord).toBeVisible();

    // Verify the record count increased
    const recordRows = page.getByRole('row');
    const count = await recordRows.count();
    expect(count).toBeGreaterThan(1);
  });

  test('should show error message when duplication fails', async ({ page }) => {
    // Wait for records to load
    await page.waitForResponse(response => response.url().includes('/api/records') && response.status() === 200);

    // Locate the record using getByRole
    const recordItem = page.getByRole('row', { name: /Sample Record/ });
    await expect(recordItem).toBeVisible();

    // Intercept the duplication request and return an error
    await page.route('**/api/records/*/duplicate', route => {
      route.abort('failed');
    });

    // Get the duplicate button using getByRole
    const duplicateButton = page.getByRole('button', { name: /Duplicate/i });
    await expect(duplicateButton).toBeVisible();

    // Click the duplicate button
    await duplicateButton.click();

    // Verify error notification appears using getByText
    const errorToast = page.getByText(/Failed to duplicate record/);
    await expect(errorToast).toBeVisible();

    // Verify that no additional record was created
    const recordRows = page.getByRole('row');
    const initialCount = await recordRows.count();

    // Attempt another duplicate to ensure the count doesn't increase
    const duplicateButtonAgain = page.getByRole('button', { name: /Duplicate/i });
    await expect(duplicateButtonAgain).toBeVisible();

    const finalCount = await recordRows.count();
    expect(finalCount).toBe(initialCount);
  });
});

