    cy.wait('@getRecordDetails');

    // Verify created date is visible
    cy.get('[data-testid="record-created-date"]')
      .should('be.visible')
      .should('contain', new Date().getFullYear().toString());

    // Verify last modified date is visible
    cy.get('[data-testid="record-modified-date"]')
      .should('be.visible')
      .should('contain', new Date().getFullYear().toString());

    // Verify date format (should match pattern like "Jan 15, 2024")
    cy.get('[data-testid="record-created-date"]').should('match', /[A-Z][a-z]{2}\s\d{1,2},\s\d{4}/);
    cy.get('[data-testid="record-modified-date"]').should('match', /[A-Z][a-z]{2}\s\d{1,2},\s\d{4}/);

    // Verify created date and modified date are the same on new record
    cy.get('[data-testid="record-created-date"]').invoke('text').then((createdText) => {
      cy.get('[data-testid="record-modified-date"]').invoke('text').should('equal', createdText);
    });
  });

  it('should update last modified date when record is edited', () => {
    // Navigate to an existing record
    cy.get('[data-testid="record-item"]').first().click();
    cy.intercept('GET', '/api/records/*').as('loadRecord');
    cy.wait('@loadRecord');

    // Capture original created date
    cy.get('[data-testid="record-created-date"]').invoke('text').as('originalCreatedDate');

    // Capture original modified date
    cy.get('[data-testid="record-modified-date"]').invoke('text').as('originalModifiedDate');

    // Edit the record
    cy.get('[data-testid="edit-record-btn"]').click();
    cy.get('[data-testid="record-name-input"]').clear().type('Updated Test Record');
    cy.get('[data-testid="save-record-btn"]').click();

    cy.intercept('PUT', '/api/records/*').as('updateRecord');
    cy.wait('@updateRecord');

    // Verify created date hasn't changed
    cy.get('[data-testid="record-created-date"]').invoke('text').should('equal', '@originalCreatedDate');

    // Verify last modified date has changed and is more recent
    cy.get('[data-testid="record-modified-date"]')
      .should('be.visible')
      .should('not.equal', '@originalModifiedDate');

    // Verify modified date contains current date
    cy.get('[data-testid="record-modified-date"]').should('contain', new Date().getFullYear().toString());
  });
});

