describe('Request Timeout Error Handling', () => {
  beforeEach(() => {
    cy.visit('/request-page');
  });

  it('should display timeout error when request exceeds 10 seconds', () => {
    // Intercept the slow endpoint and delay response beyond 10 seconds
    cy.intercept('GET', '/api/data/slow', (req) => {
      req.reply((res) => {
        res.delay(11000); // 11 seconds delay
        res.send({ statusCode: 408, body: { message: 'Request Timeout' } });
      });
    }).as('slowRequest');

    // Trigger the request
    cy.get('[data-testid="fetch-slow-data-btn"]').click();

    // Wait for the intercepted request
    cy.wait('@slowRequest');

    // Verify timeout error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Request timeout');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]')
      .should('be.visible');

    // Verify loading spinner is hidden
    cy.get('[data-testid="loading-spinner"]')
      .should('not.exist');

    // Verify retry button appears
    cy.get('[data-testid="retry-button"]')
      .should('be.visible');
  });

  it('should handle multiple timeout errors and allow retry', () => {
    // First request times out
    cy.intercept('GET', '/api/data/slow', (req) => {
      req.reply((res) => {
        res.delay(11000);
        res.send({ statusCode: 408, body: { message: 'Request Timeout' } });
      });
    }).as('firstTimeoutRequest');

    cy.get('[data-testid="fetch-slow-data-btn"]').click();
    cy.wait('@firstTimeoutRequest');

    // Verify first timeout error
    cy.get('[data-testid="error-message"]')
      .should('contain', 'Request timeout');

    // Override intercept for retry attempt - this time succeed
    cy.intercept('GET', '/api/data/slow', {
      statusCode: 200,
      body: { data: 'success' }
    }).as('successRequest');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@successRequest');

    // Verify error message is gone
    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    // Verify success data is displayed
    cy.get('[data-testid="data-display"]')
      .should('be.visible')
      .should('contain', 'success');
  });
});

