describe('Error Boundary - UI Crash Handling', () => {
  beforeEach(() => {
    cy.visit('/error-boundary-demo');
  });

  it('should display fallback UI when component crashes', () => {
    // Verify the page loads normally
    cy.get('[data-testid="app-content"]').should('be.visible');
    cy.get('[data-testid="normal-component"]').should('contain', 'Normal Operation');

    // Trigger an error by clicking the crash button
