    // Wait for error boundary to catch the error
    cy.wait(1000);

    // Verify fallback UI is displayed
    cy.get('[data-testid="error-fallback"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');
    cy.get('[data-testid="error-details"]').should('be.visible');

    // Verify the crashed component is no longer visible
    cy.get('[data-testid="normal-component"]').should('not.exist');

    // Verify recovery button is available
    cy.get('[data-testid="recover-btn"]').should('be.visible');
  });

  it('should recover from error when recovery button is clicked', () => {
    // Trigger error
    cy.get('[data-testid="trigger-crash-btn"]').click();

    // Verify error state
    cy.get('[data-testid="error-fallback"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');

    // Click recovery button
    cy.get('[data-testid="recover-btn"]').click();

