describe('JavaScript Error Recovery', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display error boundary and allow user to recover from JS error', () => {
    // Intercept API call to simulate normal operation
    cy.intercept('GET', '/api/data').as('getData');

    // Verify initial page loads successfully
    cy.get('[data-testid="app-container"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('contain', 'Welcome');

    // Trigger an action that causes a JS error
    cy.get('[data-testid="trigger-error-button"]').click();

    // Wait for error to be caught by error boundary
    cy.wait(500);

    // Verify error boundary is displayed
    cy.get('[data-testid="error-boundary"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');

    // Verify recovery button is available
    cy.get('[data-testid="recovery-button"]').should('be.visible');
    cy.get('[data-testid="recovery-button"]').click();

    // Wait for recovery API call
    cy.intercept('POST', '/api/recover').as('recover');
