import { test, expect } from '@playwright/test';

test.describe('JavaScript Error Recovery', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display error boundary and allow user to recover from JS error', async ({ page }) => {
    // Verify initial page loads successfully
    const appContainer = page.getByRole('main');
    await expect(appContainer).toBeVisible();

    const welcomeText = page.getByText('Welcome');
    await expect(welcomeText).toBeVisible();

    // Trigger an action that causes a JS error
    const triggerButton = page.getByRole('button', { name: /trigger error/i });
    await triggerButton.click();

    // Wait for error boundary to catch the error
    await page.waitForTimeout(500);

    // Verify error boundary is displayed
    const errorBoundary = page.locator('[data-testid="error-boundary"]');
    await expect(errorBoundary).toBeVisible();

    const errorMessage = page.getByText(/something went wrong/i);
    await expect(errorMessage).toBeVisible();

    // Verify recovery button is available and clickable
    const recoveryButton = page.getByRole('button', { name: /recover/i });
    await expect(recoveryButton).toBeVisible();
    await expect(recoveryButton).toBeEnabled();

    // Set up intercept for recovery API call
    await page.route('**/api/recover', route => {
      route.abort();
      setTimeout(() => route.continue(), 100);
    });

    // Click recovery button
    await recoveryButton.click();

    // Wait for recovery
    await page.waitForTimeout(600);

    // Verify app recovered to initial state
    await expect(errorBoundary).not.toBeVisible();

    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toContainText('Welcome');
  });

  test('should handle unrecoverable errors and show fallback UI', async ({ page }) => {
