    await expect(errorMsg).toBeVisible();

    // Verify fallback UI is shown
    const fallbackUI = page.locator('[data-testid="fallback-ui"]');
    await expect(fallbackUI).toBeVisible();

    const supportContact = page.getByText(/support@example.com/i);
    await expect(supportContact).toBeVisible();

    // Verify recovery button is disabled or does not exist for unrecoverable errors
    const recoveryBtn = page.getByRole('button', { name: /recover/i });
    const exists = await recoveryBtn.isVisible().catch(() => false);

    if (exists) {
      await expect(recoveryBtn).toBeDisabled();
    } else {
