  });

  it('should display error messages with proper ARIA attributes for screen reader access', () => {
    // Happy path: Submit form with invalid data and verify error accessibility
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for error message to appear
