import { test, expect } from '@playwright/test';

test.describe('Error Messages Screen Reader Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display error messages with proper ARIA attributes for screen reader access', async ({ page }) => {
    // Happy path: Submit form with invalid data and verify error accessibility
    const emailInput = page.getByLabel('Email address');
    await emailInput.fill('invalid-email');

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Wait for error message to appear
    const emailError = page.getByRole('alert');
    await expect(emailError).toBeVisible();

    // Verify error message contains descriptive text
    await expect(emailError).toContainText('Please enter a valid email address');

    // Verify email input has aria-invalid state
    const emailInputField = page.getByLabel('Email address');
    await expect(emailInputField).toHaveAttribute('aria-invalid', 'true');

    // Verify email input has aria-describedby pointing to error message
    await expect(emailInputField).toHaveAttribute('aria-describedby', /email-error/);

    // Verify error message has aria-live attribute
    await expect(emailError).toHaveAttribute('aria-live', 'polite');

    // Verify error message is not visually hidden from screen readers
    const errorVisibility = await emailError.evaluate(el => {
      const style = window.getComputedStyle(el);
      return style.display !== 'none' && style.visibility !== 'hidden';
    });
    expect(errorVisibility).toBe(true);
  });

  test('should handle multiple error messages with proper ARIA labels and associations', async ({ page }) => {
    // Negative case: Submit empty form with multiple fields
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify error container is accessible
    const errorContainer = page.getByRole('region', { name: /Form errors/i });
    await expect(errorContainer).toBeVisible();

    // Verify all error messages are visible and have proper roles
    const allAlerts = page.locator('[role="alert"]');
    const alertCount = await allAlerts.count();
    expect(alertCount).toBeGreaterThanOrEqual(3);

    // Verify email error message
    const emailError = page.getByText('Email is required');
    await expect(emailError).toBeVisible();
    await expect(emailError).toHaveAttribute('aria-live', 'polite');

    // Verify password error message
    const passwordError = page.getByText('Password is required');
    await expect(passwordError).toBeVisible();

    // Verify email input has aria-invalid
    const emailInput = page.getByLabel('Email address');
    await expect(emailInput).toHaveAttribute('aria-invalid', 'true');

    // Verify password input has aria-invalid
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toHaveAttribute('aria-invalid', 'true');

    // Verify error messages are announced with proper live region
    const liveRegions = page.locator('[aria-live="polite"]');
    const liveCount = await liveRegions.count();
    expect(liveCount).toBeGreaterThanOrEqual(2);
