describe('Payment Card Declined Error Handling', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display clear error message when payment card is declined', () => {
    // Fill in checkout form
    cy.get('[data-testid="card-number-input"]').type('4000000000000002');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
