        message: 'Your card has been declined. Please check your card details and try again.'
      }
    }).as('paymentDeclined');

    // Submit payment form
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for API response
    cy.wait('@paymentDeclined');

