      .should('have.class', 'error-state');

    // Verify user stays on checkout page
    cy.url().should('include', '/checkout');

    // Verify payment button is re-enabled for retry
    cy.get('[data-testid="submit-payment-btn"]')
      .should('be.enabled')
      .should('not.have.class', 'loading');
  });

  it('should handle edge case of multiple declined attempts with rate limiting', () => {
    // First decline attempt
    cy.get('[data-testid="card-number-input"]').type('4000000000000002');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    cy.intercept('POST', '/api/payment/process', {
