describe('Login Spinner During Async Request', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display spinner while login request is in progress', () => {
    // Intercept the login API to simulate delay
    cy.intercept('POST', '/api/auth/login', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { token: 'abc123', userId: 'user1' }
        });
      });
    }).as('loginRequest');

    // Enter credentials
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Verify spinner is visible immediately after clicking
    cy.get('[data-testid="spinner"]').should('be.visible');
    cy.get('[data-testid="spinner-text"]').should('contain', 'Logging in...');

    // Verify login button is disabled during request
    cy.get('[data-testid="login-button"]').should('be.disabled');

    // Wait for the API call to complete
    cy.wait('@loginRequest');

    // Verify spinner disappears after request completes
    cy.get('[data-testid="spinner"]').should('not.exist');

    // Verify login button is re-enabled
    cy.get('[data-testid="login-button"]').should('not.be.disabled');

    // Verify successful login (redirect or success message)
    cy.url().should('include', '/dashboard');
  });

  it('should hide spinner and show error when login request fails', () => {
    // Intercept the login API to simulate failure
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('failedLoginRequest');

    // Enter invalid credentials
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Verify spinner is visible
    cy.get('[data-testid="spinner"]').should('be.visible');

    // Wait for the failed API call
    cy.wait('@failedLoginRequest');

    // Verify spinner is hidden after failure
    cy.get('[data-testid="spinner"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Verify login button is re-enabled for retry
    cy.get('[data-testid="login-button"]').should('not.be.disabled');

    // Verify user is still on login page
    cy.url().should('include', '/login');
  });
});

