describe('Async Image Upload with Progress Percentage', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should display progress percentage during image upload', () => {
    // Setup: intercept the upload API endpoint
    cy.intercept('POST', '/api/upload', (req) => {
      // Simulate a delayed response to allow progress tracking
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { success: true, fileId: '12345', filename: 'test.jpg' }
        });
      });
    }).as('uploadRequest');

    // Click the file input and upload an image
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-image.jpg');

    // Verify the upload button is visible and click it
    cy.get('[data-testid="upload-button"]').should('be.visible').click();

    // Assert progress bar appears and is visible
    cy.get('[data-testid="progress-bar"]').should('be.visible');

    // Monitor progress percentage updates
    cy.get('[data-testid="progress-percentage"]')
      .should('be.visible')
      .and('contain', '%');

    // Wait for the upload to complete
    cy.wait('@uploadRequest');

    // Verify final state shows 100% or success message
    cy.get('[data-testid="progress-percentage"]')
      .should('contain', '100');

    cy.get('[data-testid="upload-success-message"]')
      .should('be.visible')
      .and('contain', 'Upload complete');
  });

  it('should handle upload failure and display error state', () => {
    // Setup: intercept the upload API to return an error
    cy.intercept('POST', '/api/upload', {
      statusCode: 500,
      body: { success: false, error: 'Server error' }
    }).as('uploadError');

    // Attempt to upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-image.jpg');
    cy.get('[data-testid="upload-button"]').should('be.visible').click();

    // Progress bar should briefly appear
    cy.get('[data-testid="progress-bar"]').should('be.visible');

    // Wait for the failed request
    cy.wait('@uploadError');

    // Verify error state: progress should not reach 100%
    cy.get('[data-testid="progress-percentage"]')
      .should('not.contain', '100');

    // Verify error message is displayed
    cy.get('[data-testid="upload-error-message"]')
      .should('be.visible')
      .and('contain', 'Upload failed');

    // Verify retry button appears
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});

