describe('Modal Focus Trap', () => {
  beforeEach(() => {
    cy.visit('/modal-dialog');
  });

  it('Happy Path: Focus should be trapped inside an open modal', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Focus should be on the first focusable element in modal
    cy.get('[data-testid="modal-first-input"]').should('have.focus');

    // Tab through modal elements - focus should cycle within modal
    cy.get('[data-testid="modal-first-input"]').type('{tab}');
    cy.get('[data-testid="modal-confirm-button"]').should('have.focus');

    // Tab again - focus should go to next element, not escape to background
    cy.get('[data-testid="modal-confirm-button"]').type('{tab}');
    cy.get('[data-testid="modal-cancel-button"]').should('have.focus');

    // Tab again - should cycle back to first focusable element
    cy.get('[data-testid="modal-cancel-button"]').type('{tab}');
    cy.get('[data-testid="modal-first-input"]').should('have.focus');

    // Verify background button is NOT focused (not in tab order)
    cy.get('[data-testid="open-modal-button"]').should('not.have.focus');

    // Close modal with confirm button
    cy.get('[data-testid="modal-confirm-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('Negative Case: Focus should not escape modal with reverse tab navigation', () => {
    // Open modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Focus on last button
    cy.get('[data-testid="modal-cancel-button"]').focus();
    cy.get('[data-testid="modal-cancel-button"]').should('have.focus');

    // Shift+Tab should cycle to previous element, not escape
    cy.get('[data-testid="modal-cancel-button"]').type('{shift+tab}');
    cy.get('[data-testid="modal-confirm-button"]').should('have.focus');

    // Continue reverse tab
    cy.get('[data-testid="modal-confirm-button"]').type('{shift+tab}');
    cy.get('[data-testid="modal-first-input"]').should('have.focus');

    // Reverse tab again - should cycle to last element
    cy.get('[data-testid="modal-first-input"]').type('{shift+tab}');
    cy.get('[data-testid="modal-cancel-button"]').should('have.focus');

    // Verify background is still not in focus
    cy.get('[data-testid="background-element"]').should('not.have.focus');

    // Close with Escape key
    cy.get('[data-testid="modal-dialog"]').type('{esc}');
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });
});

