    cy.get('[data-testid="modal-close-btn"]').click();

    // Verify modal is hidden
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify focus returned to trigger button
    cy.get('[data-testid="open-modal-btn"]').should('have.focus');

    // Verify trigger button is still visible and functional
    cy.get('[data-testid="open-modal-btn"]').should('be.visible');
    cy.get('[data-testid="open-modal-btn"]').should('contain', 'Open Modal');
  });

  it('should restore focus to trigger button when modal closes via escape key - edge case', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Tab to a different element inside modal
    cy.get('[data-testid="modal-confirm-btn"]').click();

    // Close modal using Escape key
    cy.get('body').type('{esc}');

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify focus is back on trigger button, not on the confirm button
