describe('Table Row Filtering by Search Input', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should filter table rows when user types in search input - happy path', () => {
    // Verify initial table state with multiple rows
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 3);
    cy.get('[data-testid="table-row"]').first().should('contain', 'John Doe');
    cy.get('[data-testid="table-row"]').eq(1).should('contain', 'Jane Smith');
    cy.get('[data-testid="table-row"]').eq(2).should('contain', 'Bob Johnson');

    // Intercept API call for filtered results
    cy.intercept('GET', '/api/table/search*').as('searchRequest');

    // Type in search input
    cy.get('[data-testid="search-input"]').click();
    cy.get('[data-testid="search-input"]').type('John');

    // Wait for API response
    cy.wait('@searchRequest');

    // Verify filtered results
    cy.get('[data-testid="table-row"]').should('have.length', 2);
    cy.get('[data-testid="table-row"]').first().should('contain', 'John Doe');
    cy.get('[data-testid="table-row"]').eq(1).should('contain', 'Bob Johnson');
    cy.get('[data-testid="table-row"]').should('not.contain', 'Jane Smith');

    // Verify search input retains typed value
    cy.get('[data-testid="search-input"]').should('have.value', 'John');
  });

  it('should show no results message when search returns empty - negative/edge case', () => {
    // Intercept API call
    cy.intercept('GET', '/api/table/search*').as('emptySearch');

    // Type search term that returns no results
    cy.get('[data-testid="search-input"]').click();
    cy.get('[data-testid="search-input"]').type('XyzNonExistent123');

    // Wait for API response
    cy.wait('@emptySearch');

    // Verify no table rows are displayed
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify empty state message is visible
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No results found');

    // Clear search and verify all rows return
    cy.get('[data-testid="search-input"]').triple();
    cy.get('[data-testid="search-input"]').type('');

    // Wait for API to return all results
    cy.wait('@emptySearch');

    // Verify table rows are visible again
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="empty-state-message"]').should('not.exist');
  });
});

