    cy.get('[data-testid="table-column-id"]').should('not.be.visible');

    // Scroll back to verify normal behavior restored
    cy.get('[data-testid="table-scroll-container"]').scrollTo('left');
    cy.get('[data-testid="table-column-id"]').should('be.visible');
  });
});

