import { test, expect } from '@playwright/test';

test.describe('Table Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display loading state while data is fetching', async ({ page }) => {
    // Intercept the API call to simulate loading delay
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.abort();
      await route.continue();
    });

    // Use getByRole to locate refresh button
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeVisible();
    await refreshButton.click();

