    await expect(loadingSpinner).toBeVisible();

    const loadingText = page.getByText(/loading data/i);
    await expect(loadingText).toBeVisible();

    // Verify table rows are not yet visible during loading
    const tableRows = page.locator('[data-testid="table-row"]');
    await expect(tableRows).toHaveCount(0);

    // Wait for data to load
    await page.waitForTimeout(2500);

    // Verify loading state disappears
    await expect(loadingSpinner).not.toBeVisible();
    await expect(loadingText).not.toBeVisible();

    // Verify table data is now visible
    await expect(tableRows.first()).toBeVisible();
  });

  test('should handle loading state when API request fails', async ({ page }) => {
    // Intercept the API call to simulate error
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Use getByRole to locate refresh button
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeVisible();
    await refreshButton.click();

    // Verify loading state is visible
    const loadingSpinner = page.locator('[data-testid="loading-spinner"]');
    await expect(loadingSpinner).toBeVisible();

    // Wait and verify loading state disappears
