describe('Table Row Highlight on Hover', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should highlight a row when user hovers over it', () => {
    // Get the first data row in the table
    cy.get('[data-testid="table-row-1"]').should('be.visible');

    // Verify initial state - row should not have highlight class
    cy.get('[data-testid="table-row-1"]').should('not.have.class', 'row-highlighted');

    // Hover over the row
    cy.get('[data-testid="table-row-1"]').trigger('mouseenter');

    // Assert that the row is now highlighted
    cy.get('[data-testid="table-row-1"]').should('have.class', 'row-highlighted');

    // Verify the background color or styling changed
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color').and('not.equal', 'rgba(0, 0, 0, 0)');

    // Move mouse away from the row
    cy.get('[data-testid="table-row-1"]').trigger('mouseleave');

    // Assert highlight is removed
    cy.get('[data-testid="table-row-1"]').should('not.have.class', 'row-highlighted');
  });

  it('should not highlight rows when table is empty or disabled', () => {
    // Navigate to empty table view
    cy.get('[data-testid="empty-table-button"]').click();

    // Verify no rows exist
    cy.get('[data-testid="table-row-1"]').should('not.exist');

    // Navigate back to table with disabled state
    cy.get('[data-testid="table-button"]').click();
    cy.get('[data-testid="disable-table-button"]').click();

    // Attempt to hover over a disabled row
    cy.get('[data-testid="table-row-1"]').trigger('mouseenter');

    // Assert highlight class is not applied to disabled row
    cy.get('[data-testid="table-row-1"]').should('have.attr', 'aria-disabled', 'true');
    cy.get('[data-testid="table-row-1"]').should('not.have.class', 'row-highlighted');

    // Verify no visual change occurs
    cy.get('[data-testid="table-row-1"]').should('have.css', 'opacity', '0.5');
  });
});

