describe('Table Row Selection Highlighting', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should highlight selected rows with a different background color', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Get all table rows
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Click first row to select it
    cy.get('[data-testid="table-row"]').first().click();

    // Verify first row has highlight class
    cy.get('[data-testid="table-row"]').first().should('have.class', 'row-selected');

    // Verify highlight color is applied (e.g., background-color)
    cy.get('[data-testid="table-row"]').first().should('have.css', 'background-color')
      .and('not.equal', 'rgba(0, 0, 0, 0)');

    // Click second row to select it
    cy.get('[data-testid="table-row"]').eq(1).click();

    // Verify second row is now highlighted
    cy.get('[data-testid="table-row"]').eq(1).should('have.class', 'row-selected');

    // Verify first row remains highlighted (multi-select scenario)
    cy.get('[data-testid="table-row"]').first().should('have.class', 'row-selected');

    // Verify both rows have the same highlight color
    cy.get('[data-testid="table-row"]').first().should('have.css', 'background-color')
      .then((firstColor) => {
        cy.get('[data-testid="table-row"]').eq(1).should('have.css', 'background-color')
          .and('equal', firstColor);
      });
  });

  it('should remove highlight when deselecting a row', () => {
    // Select a row
    cy.get('[data-testid="table-row"]').first().click();
    cy.get('[data-testid="table-row"]').first().should('have.class', 'row-selected');

    // Get the original background color before selection
    cy.get('[data-testid="table-row"]').eq(2).should('not.have.class', 'row-selected');
    cy.get('[data-testid="table-row"]').eq(2).should('have.css', 'background-color')
      .then((unselectedColor) => {
        // Click the selected row again to deselect it
        cy.get('[data-testid="table-row"]').first().click();

        // Verify row no longer has highlight class
        cy.get('[data-testid="table-row"]').first().should('not.have.class', 'row-selected');

        // Verify background color reverts to default
        cy.get('[data-testid="table-row"]').first().should('have.css', 'background-color')
          .and('equal', unselectedColor);
      });

    // Click select-all checkbox and verify all rows are highlighted
    cy.get('[data-testid="select-all-checkbox"]').click();
    cy.get('[data-testid="table-row"]').should('have.class', 'row-selected');

    // Click clear-selection button and verify no rows are highlighted
    cy.get('[data-testid="clear-selection-btn"]').click();
    cy.get('[data-testid="table-row"]').should('not.have.class', 'row-selected');
  });
});

