    // Deselect second row
    cy.get('[data-testid="row-checkbox-2"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '2');

    // Verify badge is visible
    cy.get('[data-testid="selection-badge"]').should('be.visible');

    // Verify badge styling indicates selection count
    cy.get('[data-testid="selection-badge"]').should('have.class', 'badge-active');
