describe('Cancel In-Progress Upload', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully cancel an in-progress upload', () => {
    // Intercept the upload endpoint to simulate a long-running upload
    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(5000); // Simulate slow upload
        res.send({ statusCode: 200, body: { success: true, fileId: '12345' } });
      });
    }).as('uploadRequest');

    // Select a file for upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-file.pdf');

    // Verify file is selected
    cy.get('[data-testid="file-name-display"]').should('contain', 'sample-file.pdf');

    // Click upload button to start the upload
    cy.get('[data-testid="upload-button"]').click();

    // Verify upload progress is visible
    cy.get('[data-testid="upload-progress"]').should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('be.visible');

    // Verify cancel button becomes available during upload
    cy.get('[data-testid="cancel-upload-button"]').should('be.visible');

    // Click cancel button while upload is in progress
    cy.get('[data-testid="cancel-upload-button"]').click();

    // Verify cancel confirmation dialog appears
    cy.get('[data-testid="cancel-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-cancel-button"]').should('be.visible');

    // Confirm the cancellation
    cy.get('[data-testid="confirm-cancel-button"]').click();

    // Verify upload is cancelled
    cy.get('[data-testid="upload-progress"]').should('not.exist');
    cy.get('[data-testid="cancel-upload-button"]').should('not.exist');

    // Verify success message for cancellation
    cy.get('[data-testid="cancel-success-message"]').should('be.visible').should('contain', 'Upload cancelled');

    // Verify form is reset
    cy.get('[data-testid="file-name-display"]').should('not.exist');
    cy.get('[data-testid="upload-button"]').should('be.visible');
  });

  it('should handle cancel request failure gracefully', () => {
    // Intercept the upload endpoint
    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(3000);
        res.send({ statusCode: 200, body: { success: true } });
      });
    }).as('uploadRequest');

    // Intercept the cancel endpoint to simulate failure
    cy.intercept('POST', '/api/upload/cancel', {
      statusCode: 500,
      body: { error: 'Failed to cancel upload' }
    }).as('cancelRequest');

    // Select and start upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-file.pdf');
    cy.get('[data-testid="upload-button"]').click();

    // Wait for upload to start
    cy.get('[data-testid="upload-progress"]').should('be.visible');

    // Click cancel
    cy.get('[data-testid="cancel-upload-button"]').click();
    cy.get('[data-testid="confirm-cancel-button"]').click();

    // Wait for cancel request to fail
    cy.wait('@cancelRequest');

    // Verify error message is displayed
    cy.get('[data-testid="cancel-error-message"]').should('be.visible').should('contain', 'Failed to cancel');

    // Verify upload continues or gracefully handles the error state
    cy.get('[data-testid="upload-progress"]').should('be.visible');
    cy.get('[data-testid="retry-cancel-button"]').should('be.visible');
  });
});

