describe('File Upload Queue - Remove File Before Submit', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully remove a file from the upload queue before submission', () => {
    // Select and upload multiple files
    cy.get('[data-testid="file-input"]').selectFile([
      'cypress/fixtures/document1.pdf',
      'cypress/fixtures/document2.pdf',
      'cypress/fixtures/document3.pdf'
    ]);

    // Verify all three files are in the queue
    cy.get('[data-testid="upload-queue-item"]').should('have.length', 3);
    cy.get('[data-testid="queue-file-name"]').eq(0).should('contain', 'document1.pdf');
    cy.get('[data-testid="queue-file-name"]').eq(1).should('contain', 'document2.pdf');
    cy.get('[data-testid="queue-file-name"]').eq(2).should('contain', 'document3.pdf');

    // Remove the second file from queue
    cy.get('[data-testid="remove-file-btn"]').eq(1).click();

    // Verify the file was removed and queue now has 2 items
    cy.get('[data-testid="upload-queue-item"]').should('have.length', 2);
    cy.get('[data-testid="queue-file-name"]').eq(0).should('contain', 'document1.pdf');
    cy.get('[data-testid="queue-file-name"]').eq(1).should('contain', 'document3.pdf');

    // Verify remove success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File removed from queue');

    // Submit the remaining files
    cy.get('[data-testid="submit-upload-btn"]').click();

    // Intercept and verify API call contains only 2 files
    cy.intercept('POST', '/api/upload').as('fileUpload');
    cy.wait('@fileUpload').then((interception) => {
      expect(interception.request.body).to.include('document1.pdf');
      expect(interception.request.body).to.include('document3.pdf');
      expect(interception.request.body).not.to.include('document2.pdf');
    });

    // Verify success response
    cy.get('[data-testid="upload-success"]').should('be.visible').should('contain', '2 files uploaded successfully');
  });

  it('should handle edge case of removing all files from queue and preventing submission', () => {
    // Upload a single file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document1.pdf');

    // Verify file is in queue
    cy.get('[data-testid="upload-queue-item"]').should('have.length', 1);

    // Remove the only file
    cy.get('[data-testid="remove-file-btn"]').click();

    // Verify queue is empty
    cy.get('[data-testid="upload-queue-item"]').should('not.exist');
    cy.get('[data-testid="empty-queue-message"]').should('be.visible').should('contain', 'No files in queue');

    // Verify submit button is disabled when queue is empty
    cy.get('[data-testid="submit-upload-btn"]').should('be.disabled');

    // Attempt to submit empty queue via API should not trigger
    cy.intercept('POST', '/api/upload').as('fileUpload');
    cy.get('[data-testid="submit-upload-btn"]').click();
    cy.get('@fileUpload').should('not.exist');

    // Verify validation error message
    cy.get('[data-testid="validation-error"]').should('be.visible').should('contain', 'Please add files before submitting');
  });
});

