    await expect(submitButton).toBeVisible();
    await submitButton.click();

    // Intercept and verify API call contains only 2 files
    const uploadPromise = page.waitForResponse(response => response.url().includes('/api/upload') && response.status() === 200);
    const uploadResponse = await uploadPromise;
    const responseBody = await uploadResponse.text();
    expect(responseBody).toContain('document1.pdf');
    expect(responseBody).toContain('document3.pdf');
    expect(responseBody).not.toContain('document2.pdf');

    // Verify success response
    const uploadSuccess = page.locator('[data-testid="upload-success"]');
    await expect(uploadSuccess).toBeVisible();
    await expect(uploadSuccess).toContainText('2 files uploaded successfully');
