  test('should handle edge case of removing all files from queue and preventing submission', async ({ page }) => {
    // Upload a single file
    const fileInput = page.locator('[data-testid="file-input"]');
    await fileInput.setInputFiles('playwright/fixtures/document1.pdf');

    // Verify file is in queue
    const queueItems = page.locator('[data-testid="upload-queue-item"]');
    await expect(queueItems).toHaveCount(1);

    // Remove the only file
    const removeButton = page.getByRole('button', { name: /remove/i }).first();
    await expect(removeButton).toBeVisible();
    await removeButton.click();

    // Verify queue is empty
    await expect(queueItems).toHaveCount(0);

    const emptyMessage = page.locator('[data-testid="empty-queue-message"]');
    await expect(emptyMessage).toBeVisible();
    await expect(emptyMessage).toContainText('No files in queue');

    // Verify submit button is disabled when queue is empty
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Verify validation error message appears on disabled submit attempt
    const validationError = page.locator('[data-testid="validation-error"]');
    await expect(validationError).toBeVisible();
    await expect(validationError).toContainText('Please add files before submitting');

    // Verify no upload request is made when queue is empty
    let uploadRequested = false;
    page.on('response', response => {
      if (response.url().includes('/api/upload')) {
        uploadRequested = true;
      }
    });

    // Attempt to submit should not trigger API call
    await submitButton.click();
    expect(uploadRequested).toBe(false);
  });
});

