describe('File Upload Retry Functionality', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should retry a failed upload without re-selecting the file', () => {
    // Intercept the initial upload request to simulate failure
    cy.intercept('POST', '/api/upload', { statusCode: 500, body: { error: 'Server error' } }).as('uploadFail');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf');

    // Verify file is selected
    cy.get('[data-testid="file-name"]').should('contain', 'test-file.pdf');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for failed request
    cy.wait('@uploadFail');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Upload failed');

    // Intercept the retry request to simulate success
    cy.intercept('POST', '/api/upload', { statusCode: 200, body: { success: true, fileId: 'file123' } }).as('uploadSuccess');

    // Click retry button without re-selecting file
    cy.get('[data-testid="retry-button"]').click();

    // Wait for successful request
    cy.wait('@uploadSuccess');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Upload successful');

    // Verify file name is still displayed
    cy.get('[data-testid="file-name"]').should('contain', 'test-file.pdf');
  });

  it('should handle retry failure and allow multiple retry attempts', () => {
    // Intercept initial upload request to fail
    cy.intercept('POST', '/api/upload', { statusCode: 500, body: { error: 'Network error' } }).as('uploadFail1');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-document.docx');

    // Verify file is selected
    cy.get('[data-testid="file-name"]').should('contain', 'test-document.docx');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for first failure
    cy.wait('@uploadFail1');

    // Verify error is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Intercept second retry to also fail
    cy.intercept('POST', '/api/upload', { statusCode: 503, body: { error: 'Service unavailable' } }).as('uploadFail2');

    // Click retry button first time
    cy.get('[data-testid="retry-button"]').click();

    // Wait for second failure
    cy.wait('@uploadFail2');

    // Verify error persists and file is still selected
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="file-name"]').should('contain', 'test-document.docx');

    // Intercept third retry to succeed
    cy.intercept('POST', '/api/upload', { statusCode: 200, body: { success: true, fileId: 'file456' } }).as('uploadSuccess');

    // Click retry button second time
    cy.get('[data-testid="retry-button"]').click();

    // Wait for success
    cy.wait('@uploadSuccess');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Upload successful');
  });
});

