describe('Upload Button Disabled State During File Upload', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should disable upload button while file is uploading and enable after completion', () => {
    // Setup: intercept the file upload API to simulate delay
    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { success: true, filename: 'test-file.pdf' },
        });
      });
    }).as('fileUpload');

    // Select a file to upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-file.pdf');

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Assert that upload button is disabled during upload
    cy.get('[data-testid="upload-button"]').should('be.disabled');
    cy.get('[data-testid="upload-button"]').should('contain', 'Uploading...');

    // Wait for the upload to complete
    cy.wait('@fileUpload');

    // Assert that upload button is enabled after upload completes
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');
    cy.get('[data-testid="upload-button"]').should('contain', 'Upload File');

    // Assert success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');
  });

  it('should keep upload button disabled if upload fails and allow retry', () => {
    // Setup: intercept the file upload API to simulate failure
    cy.intercept('POST', '/api/upload', {
      statusCode: 500,
      body: { error: 'Server error during upload' },
    }).as('fileUploadFail');

    // Select a file to upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-file.pdf');

    // Click the upload button
