describe('Image Paste from Clipboard - Upload Area', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully paste image from clipboard into upload area', () => {
    // Mock the clipboard paste event with an image file
    const fileName = 'test-image.png';
    const fileType = 'image/png';

    cy.fixture('test-image.png', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent, fileType))
      .then(blob => {
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(new File([blob], fileName, { type: fileType }));

        cy.get('[data-testid="upload-area"]').then($element => {
          const pasteEvent = new ClipboardEvent('paste', {
            clipboardData: dataTransfer,
            bubbles: true,
            cancelable: true,
          });
          $element[0].dispatchEvent(pasteEvent);
        });
      });

    // Verify image was uploaded successfully
    cy.get('[data-testid="upload-area"]').should('be.visible');
    cy.get('[data-testid="upload-preview"]').should('be.visible');
