    cy.get('[data-testid="confirm-button"]').should('be.visible').click();
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Image uploaded');
  });

  it('should reject non-image files pasted into upload area', () => {
    // Mock the clipboard paste event with a non-image file
    const fileName = 'document.txt';
    const fileType = 'text/plain';

    cy.fixture('document.txt', 'utf-8')
      .then(fileContent => Cypress.Blob.stringToBlob(fileContent, fileType))
      .then(blob => {
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(new File([blob], fileName, { type: fileType }));

        cy.get('[data-testid="upload-area"]').then($element => {
          const pasteEvent = new ClipboardEvent('paste', {
            clipboardData: dataTransfer,
            bubbles: true,
            cancelable: true,
          });
          $element[0].dispatchEvent(pasteEvent);
        });
      });

    // Verify error message is displayed
