describe('Faceted Search - Results Update Without Full Page Reload', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should update search results when applying a facet filter without page reload', () => {
    // Initial search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Wait for initial results API call
    cy.intercept('GET', '/api/search?q=laptop').as('initialSearch');
    cy.wait('@initialSearch');

    // Verify initial results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Store initial result count
    cy.get('[data-testid="result-item"]').then(($results) => {
      const initialCount = $results.length;

      // Apply facet filter (e.g., price range)
      cy.get('[data-testid="facet-price-500-1000"]').click();

      // Intercept the faceted search API call
      cy.intercept('GET', '/api/search?q=laptop&price=500-1000').as('facetedSearch');
      cy.wait('@facetedSearch');

      // Verify page did not reload by checking that search input still contains value
      cy.get('[data-testid="search-input"]').should('have.value', 'laptop');

      // Verify results were updated
      cy.get('[data-testid="search-results"]').should('be.visible');
      cy.get('[data-testid="result-item"]').should('have.length.lessThan', initialCount);

      // Verify facet filter is marked as active
      cy.get('[data-testid="facet-price-500-1000"]').should('have.class', 'active');

      // Verify result count text updated
      cy.get('[data-testid="results-count"]').should('contain', 'results');
    });
  });

  it('should handle edge case when facet filter returns no results', () => {
    // Initial search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    cy.intercept('GET', '/api/search?q=laptop').as('initialSearch');
    cy.wait('@initialSearch');

    cy.get('[data-testid="search-results"]').should('be.visible');

    // Apply facet filter that returns no results
    cy.get('[data-testid="facet-brand-obscure"]').click();

    cy.intercept('GET', '/api/search?q=laptop&brand=obscure').as('noResultsSearch');
    cy.wait('@noResultsSearch');

    // Verify page did not reload
    cy.get('[data-testid="search-input"]').should('have.value', 'laptop');

    // Verify no results message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');

