  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display tags for each active filter above results', async ({ page }) => {
    // Apply first filter using getByRole
    const categoryButton = page.getByRole('button', { name: /category/i });
    await categoryButton.click();
    const electronicsOption = page.getByRole('option', { name: /electronics/i });
    await electronicsOption.click();

    // Apply second filter using getByRole
    const priceButton = page.getByRole('button', { name: /price/i });
    await priceButton.click();
    const priceOption = page.getByRole('option', { name: /under \$100/i });
    await priceOption.click();

    // Apply third filter
    const brandButton = page.getByRole('button', { name: /brand/i });
    await brandButton.click();
    const brandOption = page.getByRole('option', { name: /samsung/i });
    await brandOption.click();

    // Verify filter tags container is visible
    const filtersContainer = page.locator('[data-testid="active-filters-container"]');
    await expect(filtersContainer).toBeVisible();

    // Verify each filter tag is displayed with correct text
    const electronicsTag = page.getByText('Electronics', { exact: true });
    await expect(electronicsTag).toBeVisible();

    const priceTag = page.getByText('Under $100', { exact: true });
    await expect(priceTag).toBeVisible();

    const brandTag = page.getByText('Samsung', { exact: true });
    await expect(brandTag).toBeVisible();

    // Verify results section is visible below tags
    const resultsSection = page.locator('[data-testid="search-results"]');
    await expect(resultsSection).toBeVisible();
    const resultItems = page.locator('[data-testid="result-item"]');
    await expect(resultItems.first()).toBeVisible();
  });

  test('should remove filter tag when close button is clicked and update results', async ({ page }) => {
    // Apply multiple filters using getByRole
    const categoryButton = page.getByRole('button', { name: /category/i });
    await categoryButton.click();
    const electronicsOption = page.getByRole('option', { name: /electronics/i });
    await electronicsOption.click();

    const priceButton = page.getByRole('button', { name: /price/i });
    await priceButton.click();
    const priceOption = page.getByRole('option', { name: /under \$100/i });
    await priceOption.click();

    // Wait for initial results to load
    await page.waitForSelector('[data-testid="result-item"]', { state: 'visible' });

    // Get initial result count
    const initialResultCount = await page.locator('[data-testid="result-item"]').count();
    expect(initialResultCount).toBeGreaterThan(0);

    // Find and click the remove button on Electronics tag
    const electronicsTagContainer = page.locator('[data-testid="filter-tag-electronics"]');
    const removeButton = electronicsTagContainer.getByRole('button', { name: /remove|close|x/i });
    await removeButton.click();

    // Wait for results to update after filter removal
    await page.waitForTimeout(500);

    // Verify Electronics tag is removed
    const electronicsTag = page.getByText('Electronics', { exact: true });
    await expect(electronicsTag).not.toBeVisible();

    // Verify Under $100 tag still exists
    const priceTag = page.getByText('Under $100', { exact: true });
    await expect(priceTag).toBeVisible();

    // Verify results are still displayed
    const resultItems = page.locator('[data-testid="result-item"]');
    await expect(resultItems.first()).toBeVisible();
  });
});

