describe('Remove Individual Filter Tags', () => {
  beforeEach(() => {
    cy.visit('/search');
    // Setup: Add multiple filter tags
    cy.get('[data-testid="filter-input"]').type('category:electronics');
    cy.get('[data-testid="apply-filter-btn"]').click();
    cy.get('[data-testid="filter-input"]').type('price:low');
    cy.get('[data-testid="apply-filter-btn"]').click();
    cy.get('[data-testid="filter-input"]').type('brand:samsung');
    cy.get('[data-testid="apply-filter-btn"]').click();
  });

  it('should remove a filter tag when clicking the x icon', () => {
    // Verify all three tags are visible
    cy.get('[data-testid="filter-tag-category"]').should('be.visible');
    cy.get('[data-testid="filter-tag-price"]').should('be.visible');
    cy.get('[data-testid="filter-tag-brand"]').should('be.visible');

    // Click the x icon on the "price" tag
    cy.get('[data-testid="filter-tag-price"] [data-testid="remove-tag-btn"]').click();

    // Verify the price tag is removed
    cy.get('[data-testid="filter-tag-price"]').should('not.exist');

    // Verify other tags remain
    cy.get('[data-testid="filter-tag-category"]').should('be.visible');
    cy.get('[data-testid="filter-tag-brand"]').should('be.visible');

    // Verify search results are updated
    cy.get('[data-testid="search-results"]').should('contain', 'Showing results');
  });

  it('should handle removing the last remaining filter tag', () => {
    // Remove category tag
    cy.get('[data-testid="filter-tag-category"] [data-testid="remove-tag-btn"]').click();
    cy.get('[data-testid="filter-tag-category"]').should('not.exist');

    // Remove price tag
    cy.get('[data-testid="filter-tag-price"] [data-testid="remove-tag-btn"]').click();
    cy.get('[data-testid="filter-tag-price"]').should('not.exist');

    // Remove brand tag (the last one)
    cy.get('[data-testid="filter-tag-brand"] [data-testid="remove-tag-btn"]').click();
    cy.get('[data-testid="filter-tag-brand"]').should('not.exist');

    // Verify no filter tags container is visible or it's empty
    cy.get('[data-testid="filter-tags-container"]').should('be.empty');

    // Verify search shows all results
    cy.get('[data-testid="search-results"]').should('contain', 'Showing all results');
  });
});

