import { test, expect } from '@playwright/test';

test.describe('Search Spelling Tolerance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should return results for minor spelling mistakes', async ({ page }) => {
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('chocolte');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    const firstResult = page.getByText('chocolate', { exact: false });
    await expect(firstResult).toBeVisible();

    const resultCount = page.getByText(/\d+ results found/);
    await expect(resultCount).toBeVisible();
  });

  test('should handle multiple spelling errors and suggest corrections', async ({ page }) => {
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('chcolte');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    const didYouMean = page.getByRole('region', { name: /did you mean/i });
    await expect(didYouMean).toBeVisible();

    const suggestionLink = page.getByRole('link', { name: /chocolate/i });
    await expect(suggestionLink).toBeVisible();

    const emptyState = page.getByText(/no results found/i);
    await expect(emptyState).toBeVisible();

    await suggestionLink.click();
    const correctedInput = page.getByPlaceholder('Search products...');
    await expect(correctedInput).toHaveValue('chocolate');
  });
});

