import { test, expect } from '@playwright/test';

test.describe('Search Results - Highlighted Search Terms', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should highlight search terms in result snippets - happy path', async ({ page }) => {
    // Setup: listen for API response
    await page.route('/api/search*', (route) => {
      route.continue();
    });

    // Locate and interact with search input using getByRole
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('playwright testing');

    // Locate and click search button using getByRole
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for search results to load
    await page.waitForSelector('[data-testid="search-results"]');

    // Verify search results container is visible
    const resultsContainer = page.locator('[data-testid="search-results"]');
    await expect(resultsContainer).toBeVisible();

    // Verify first result snippet exists and is visible
    const firstSnippet = page.locator('[data-testid="result-snippet-0"]');
    await expect(firstSnippet).toBeVisible();

    // Verify highlighted terms exist in first result
    const highlightedTerms = page.locator('[data-testid="result-snippet-0"] [data-testid="highlighted-term"]');
    await expect(highlightedTerms.first()).toContainText('playwright');

    // Verify highlight styling is applied
    const firstHighlight = page.locator('[data-testid="result-snippet-0"] [data-testid="highlighted-term"]').first();
    await expect(firstHighlight).toHaveCSS('background-color', /rgb/);

    // Verify multiple highlights exist across results
    const allHighlights = page.locator('[data-testid="search-results"] [data-testid="highlighted-term"]');
    const highlightCount = await allHighlights.count();
    expect(highlightCount).toBeGreaterThan(2);

    // Verify second result also has highlights
    const secondSnippetHighlight = page.locator('[data-testid="result-snippet-1"] [data-testid="highlighted-term"]').first();
    await expect(secondSnippetHighlight).toBeVisible();
  });

  test('should handle edge case with no matching terms to highlight', async ({ page }) => {
    // Setup: intercept API
    await page.route('/api/search*', (route) => {
      route.continue();
    });

    // Locate search input using getByRole
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('xyznonexistentterm9999');

    // Locate and click search button using getByRole
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for results to load
    await page.waitForSelector('[data-testid="search-results"]', { state: 'attached' });

    // Verify results container is visible
    const resultsContainer = page.locator('[data-testid="search-results"]');
    await expect(resultsContainer).toBeVisible();

    // Verify no highlighted terms exist when no matches found
    const highlightedTerms = page.locator('[data-testid="search-results"] [data-testid="highlighted-term"]');
    await expect(highlightedTerms).toHaveCount(0);

    // Verify no results message is displayed
    const noResultsMessage = page.getByText(/no results found/i);
    await expect(noResultsMessage).toBeVisible();

    // Clear search input and verify it's empty
    await searchInput.clear();
    await expect(searchInput).toHaveValue('');
  });
});

