describe('Filter List by Multiple Statuses', () => {
  beforeEach(() => {
    cy.visit('/list');
  });

  it('should filter list by multiple statuses simultaneously', () => {
    // Verify initial list is visible
    cy.get('[data-testid="list-container"]').should('be.visible');
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);

    // Open filter panel
    cy.get('[data-testid="filter-button"]').click();
    cy.get('[data-testid="filter-panel"]').should('be.visible');

    // Select first status checkbox
    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="status-filter-active"]').should('be.checked');

    // Select second status checkbox
    cy.get('[data-testid="status-filter-pending"]').click();
    cy.get('[data-testid="status-filter-pending"]').should('be.checked');

    // Apply filters
    cy.get('[data-testid="apply-filter-button"]').click();

    // Intercept API call for filtered results
    cy.intercept('GET', '/api/items?status=active&status=pending').as('filterResults');
    cy.wait('@filterResults');

    // Verify filtered results are displayed
    cy.get('[data-testid="list-item"]').should('be.visible');
    cy.get('[data-testid="filter-badge-active"]').should('contain', 'Active');
    cy.get('[data-testid="filter-badge-pending"]').should('contain', 'Pending');

    // Verify completed status items are not in list
    cy.get('[data-testid="list-item-completed"]').should('not.exist');
  });

  it('should handle edge case when no statuses are selected', () => {
    // Open filter panel
    cy.get('[data-testid="filter-button"]').click();
    cy.get('[data-testid="filter-panel"]').should('be.visible');

    // Uncheck all status filters if any are pre-selected
    cy.get('[data-testid="status-filter-active"]').uncheck({ force: true });
    cy.get('[data-testid="status-filter-pending"]').uncheck({ force: true });
    cy.get('[data-testid="status-filter-completed"]').uncheck({ force: true });

    // Attempt to apply empty filter
    cy.get('[data-testid="apply-filter-button"]').click();

    // Verify warning message is shown
    cy.get('[data-testid="filter-warning"]').should('be.visible');
    cy.get('[data-testid="filter-warning"]').should('contain', 'Please select at least one status');

    // Verify list remains unchanged
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
  });
});

