import { test, expect } from '@playwright/test';

test.describe('Filter List by Multiple Statuses', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/list');
  });

  test('should filter list by multiple statuses simultaneously', async ({ page }) => {
    // Verify initial list is visible
    const listContainer = page.locator('[data-testid="list-container"]');
    await expect(listContainer).toBeVisible();

    const listItems = page.locator('[data-testid="list-item"]');
    const initialCount = await listItems.count();
    expect(initialCount).toBeGreaterThan(0);

    // Open filter panel using getByRole
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    const filterPanel = page.locator('[data-testid="filter-panel"]');
    await expect(filterPanel).toBeVisible();

    // Select first status checkbox using getByLabel
    const activeStatusCheckbox = page.getByLabel(/active/i);
    await activeStatusCheckbox.click();
    await expect(activeStatusCheckbox).toBeChecked();

    // Select second status checkbox
    const pendingStatusCheckbox = page.getByLabel(/pending/i);
    await pendingStatusCheckbox.click();
    await expect(pendingStatusCheckbox).toBeChecked();

    // Apply filters using getByRole
    const applyButton = page.getByRole('button', { name: /apply/i });

    // Intercept API call for filtered results
    await page.route('/api/items?status=active&status=pending', route => {
      route.continue();
    });

    await applyButton.click();
    await page.waitForLoadState('networkidle');

    // Verify filtered results are displayed
    await expect(listItems.first()).toBeVisible();

    const activeFilterBadge = page.locator('[data-testid="filter-badge-active"]');
    const pendingFilterBadge = page.locator('[data-testid="filter-badge-pending"]');

    await expect(activeFilterBadge).toContainText('Active');
    await expect(pendingFilterBadge).toContainText('Pending');

    // Verify completed status items are not in list
    const completedItems = page.locator('[data-testid="list-item-completed"]');
    await expect(completedItems).not.toBeVisible();
  });

  test('should handle edge case when no statuses are selected', async ({ page }) => {
    // Open filter panel using getByRole
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    const filterPanel = page.locator('[data-testid="filter-panel"]');
    await expect(filterPanel).toBeVisible();

    // Uncheck all status filters using getByLabel
    const activeStatusCheckbox = page.getByLabel(/active/i);
    const pendingStatusCheckbox = page.getByLabel(/pending/i);
    const completedStatusCheckbox = page.getByLabel(/completed/i);

    await activeStatusCheckbox.uncheck({ force: true });
    await pendingStatusCheckbox.uncheck({ force: true });
    await completedStatusCheckbox.uncheck({ force: true });

    // Verify all are unchecked
    await expect(activeStatusCheckbox).not.toBeChecked();
    await expect(pendingStatusCheckbox).not.toBeChecked();
    await expect(completedStatusCheckbox).not.toBeChecked();

    // Attempt to apply empty filter using getByRole
    const applyButton = page.getByRole('button', { name: /apply/i });
    await applyButton.click();

    // Verify warning message is shown
    const warningMessage = page.locator('[data-testid="filter-warning"]');
    await expect(warningMessage).toBeVisible();
    await expect(warningMessage).toContainText('Please select at least one status');

    // Verify list remains unchanged
    const listItems = page.locator('[data-testid="list-item"]');
    const itemCount = await listItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });
});

