import { test, expect } from '@playwright/test';

test.describe('WCAG 2.1 AA Color Contrast Standards', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/accessibility-test-page');
  });

  test('should have sufficient color contrast on primary buttons meeting WCAG AA standards', async ({ page }) => {
    // Locate and verify primary button by role
    const primaryButton = page.getByRole('button', { name: /submit/i });
    await expect(primaryButton).toBeVisible();

    // Get computed styles to verify contrast
    const buttonStyles = await primaryButton.evaluate((el) => {
      const computed = window.getComputedStyle(el);
      return {
        backgroundColor: computed.backgroundColor,
        color: computed.color,
        cursor: computed.cursor
      };
    });

    // Verify button is interactive with proper cursor
    expect(buttonStyles.cursor).toBe('pointer');

    // Click the button to trigger action
    await primaryButton.click();

    // Verify success feedback maintains contrast
    const successMessage = page.getByRole('status');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText(/success|submitted/i);

    // Verify heading has proper contrast
    const heading = page.getByRole('heading', { level: 1 });
    await expect(heading).toBeVisible();
  });

  test('should flag insufficient contrast on low-contrast text elements as a negative case', async ({ page }) => {
    // Locate low-contrast element by text
    const lowContrastText = page.getByText(/low contrast text/i);
    await expect(lowContrastText).toBeVisible();

    // Verify warning alert is displayed for accessibility violation
    const contrastWarning = page.getByRole('alert');
    await expect(contrastWarning).toBeVisible();
    await expect(contrastWarning).toContainText(/insufficient contrast/i);

    // Locate and click the contrast check button
    const checkButton = page.getByRole('button', { name: /check contrast/i });
    await expect(checkButton).toBeVisible();
    await checkButton.click();

    // Wait for and verify API response
    const response = await page.waitForResponse(
      response => response.url().includes('/api/accessibility/check-contrast') && response.status() === 200
    );
    expect(response.status()).toBe(200);

    // Verify warning persists after check
    await expect(contrastWarning).toBeVisible();
    await expect(contrastWarning).toContainText(/insufficient contrast/i);
  });
});

