describe('Icon Button Accessibility - Accessible Names', () => {
  beforeEach(() => {
    cy.visit('/components/icon-buttons');
  });

  it('should have accessible names on all icon buttons', () => {
    // Verify that all icon buttons have aria-label attributes
    cy.get('[data-testid="icon-button"]').each(($button) => {
      cy.wrap($button).should('have.attr', 'aria-label');
      cy.wrap($button).invoke('attr', 'aria-label').should('not.be.empty');
    });

    // Verify specific icon buttons have correct accessible names
    cy.get('[data-testid="delete-button"]')
      .should('have.attr', 'aria-label', 'Delete item')
      .should('be.visible');

    cy.get('[data-testid="edit-button"]')
      .should('have.attr', 'aria-label', 'Edit item')
      .should('be.visible');

    cy.get('[data-testid="close-button"]')
      .should('have.attr', 'aria-label', 'Close dialog')
      .should('be.visible');

    // Verify icon buttons are keyboard accessible
    cy.get('[data-testid="delete-button"]').focus().should('have.focus');
    cy.get('[data-testid="delete-button"]').type('{enter}');
    cy.intercept('DELETE', '/api/items/*').as('deleteItem');
    cy.wait('@deleteItem').its('response.statusCode').should('equal', 200);
  });

  it('should fail when icon buttons lack accessible names', () => {
    // Verify that buttons without aria-label are identified as inaccessible
    cy.get('[data-testid="unlabeled-icon-button"]').should('exist');
    cy.get('[data-testid="unlabeled-icon-button"]')
      .should('not.have.attr', 'aria-label');

