    cy.get('[data-testid="empty-label-button"]').should('exist');
    cy.get('[data-testid="empty-label-button"]')
      .invoke('attr', 'aria-label')
      .should('be.empty');

    // Verify that icon buttons without title attribute lack fallback accessibility
    cy.get('[data-testid="no-title-button"]')
      .should('not.have.attr', 'title');

    // Attempt to focus unlabeled button and verify screen reader would not announce purpose
    cy.get('[data-testid="unlabeled-icon-button"]').focus();
    cy.get('[data-testid="unlabeled-icon-button"]')
      .invoke('attr', 'aria-label')
      .should('not.exist');
  });
});

