describe('Dropdown Escape Key Accessibility', () => {
  beforeEach(() => {
    cy.visit('/dropdowns');
  });

  it('should close dropdown when Escape key is pressed', () => {
    // Open the first dropdown
    cy.get('[data-testid="user-menu-button"]').click();

    // Verify dropdown is visible
    cy.get('[data-testid="user-menu-dropdown"]').should('be.visible');
    cy.get('[data-testid="dropdown-item-profile"]').should('be.visible');

    // Press Escape key
    cy.get('body').type('{esc}');

    // Verify dropdown is closed
    cy.get('[data-testid="user-menu-dropdown"]').should('not.exist');
    cy.get('[data-testid="dropdown-item-profile"]').should('not.exist');

    // Verify focus management (focus should return to trigger button)
    cy.get('[data-testid="user-menu-button"]').should('have.focus');
  });

  it('should not close dropdown when other keys are pressed and handle nested dropdowns', () => {
    // Open first dropdown
    cy.get('[data-testid="filters-button"]').click();
    cy.get('[data-testid="filters-dropdown"]').should('be.visible');

    // Press Enter key (should not close)
