    // Parent dropdown should still be visible
    cy.get('[data-testid="filters-dropdown"]').should('be.visible');

    // Press Escape again - should close parent dropdown
    cy.get('body').type('{esc}');
    cy.get('[data-testid="filters-dropdown"]').should('not.exist');
    cy.get('[data-testid="filters-button"]').should('have.focus');
  });
});

