    cy.get('[data-testid="secondary-button"]').should('be.visible');
    cy.get('[data-testid="secondary-button"]').should('contain', 'Learn More');

    cy.get('[data-testid="footer-content"]').should('be.visible');
    cy.get('[data-testid="footer-content"]').should('contain', 'Footer');

    // Verify DOM order matches visual order by checking tabindex
    cy.get('[data-testid="primary-button"]').should('have.attr', 'tabindex', '0');
    cy.get('[data-testid="secondary-button"]').should('have.attr', 'tabindex', '0');

    // Verify no elements are hidden in DOM but visible to users (negative z-index, etc)
    cy.get('[data-testid="intro-paragraph"]').should('have.css', 'position').and('not.equal', 'absolute');
  });

  it('should identify when reading order does not match visual order (negative case)', () => {
