    // Verify footer content
    const footerContent = page.getByText(/Footer/);
    await expect(footerContent).toBeVisible();

    // Verify tabindex is correct
    await expect(primaryButton).toHaveAttribute('tabindex', '0');
    await expect(secondaryButton).toHaveAttribute('tabindex', '0');

    // Check that elements are not absolutely positioned in a way that breaks order
    const introParagraphElement = page.locator('[data-testid="intro-paragraph"]');
    const computedStyle = await introParagraphElement.evaluate(el => window.getComputedStyle(el).position);
    expect(computedStyle).not.toBe('absolute');

    // Verify reading order by navigating with Tab key
    await mainHeading.focus();
    let focusedElement = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    expect(focusedElement).toBe('main-heading');
  });

  test('should identify when reading order does not match visual order (negative case)', async ({ page }) => {
    // Verify skip link exists and is accessible
    const skipLink = page.getByRole('link', { name: /Skip to main content/i });
    await expect(skipLink).toBeVisible();

    // Get primary navigation button
    const navButton = page.getByRole('button', { name: /Menu/i });
    if (await navButton.isVisible()) {
      await expect(navButton).toBeVisible();
    }

    // Ensure misaligned content does not exist
    const misalignedContent = page.locator('[data-testid="misaligned-content"]');
    await expect(misalignedContent).not.toBeVisible();

    // Verify no extreme negative margins breaking reading order
    const buttons = page.getByRole('button');
    const buttonCount = await buttons.count();
    for (let i = 0; i < buttonCount; i++) {
      const button = buttons.nth(i);
      const marginLeft = await button.evaluate(el => window.getComputedStyle(el).marginLeft);
      const marginTop = await button.evaluate(el => window.getComputedStyle(el).marginTop);
      expect(marginLeft).not.toBe('-9999px');
      expect(marginTop).not.toBe('-9999px');
    }

    // Verify decorative elements are properly marked as hidden
    const decorativeElements = page.locator('[aria-hidden="true"]');
    const decorativeCount = await decorativeElements.count();
    for (let i = 0; i < decorativeCount; i++) {
      const element = decorativeElements.nth(i);
      const tabindex = await element.getAttribute('tabindex');
      expect(tabindex).toBeFalsy();
    }

    // Verify focus follows visual order after interaction
    const primaryButton = page.getByRole('button', { name: /Get Started/i });
    await primaryButton.click();
    await expect(primaryButton).toBeFocused();
