describe('Toast Notifications Accessibility - Screen Reader Announcements', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should announce success toast notification to screen readers with proper ARIA live region', () => {
    // Trigger success notification
    cy.get('[data-testid="trigger-success-btn"]').click();

    // Verify toast container has proper ARIA attributes for screen reader announcement
    cy.get('[data-testid="toast-container"]').should('have.attr', 'role', 'status');
    cy.get('[data-testid="toast-container"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="toast-container"]').should('have.attr', 'aria-atomic', 'true');

    // Verify toast message is visible
    cy.get('[data-testid="toast-message"]').should('be.visible');
    cy.get('[data-testid="toast-message"]').should('contain', 'Operation completed successfully');

    // Verify toast has appropriate semantic content for screen readers
    cy.get('[data-testid="toast-message"]').should('have.attr', 'id');

    // Verify close button is accessible with proper aria-label
    cy.get('[data-testid="toast-close-btn"]').should('have.attr', 'aria-label', 'Close notification');
    cy.get('[data-testid="toast-close-btn"]').click();

    // Verify toast is removed after closing
    cy.get('[data-testid="toast-message"]').should('not.exist');
  });

  it('should handle urgent error toast with assertive ARIA live region for screen readers', () => {
    // Trigger error notification
    cy.get('[data-testid="trigger-error-btn"]').click();

    // Verify error toast uses assertive live region for urgent announcements
    cy.get('[data-testid="toast-container"]').should('have.attr', 'role', 'alert');
    cy.get('[data-testid="toast-container"]').should('have.attr', 'aria-live', 'assertive');
    cy.get('[data-testid="toast-container"]').should('have.attr', 'aria-atomic', 'true');

    // Verify error message content
    cy.get('[data-testid="toast-message"]').should('be.visible');
