describe('Mobile Touch Target Size - Responsive Design', () => {
  beforeEach(() => {
    cy.visit('/mobile-ui');
    // Set viewport to mobile size
    cy.viewport('iphone-x');
  });

  it('should have touch targets with minimum 44x44px size on mobile devices', () => {
    // Get primary action button
    cy.get('[data-testid="primary-action-btn"]').should('be.visible');

    // Verify button is large enough to tap (minimum 44x44px)
    cy.get('[data-testid="primary-action-btn"]').then(($btn) => {
      const height = $btn.height();
      const width = $btn.width();
      expect(height).to.be.at.least(44);
      expect(width).to.be.at.least(44);
    });

    // Verify icon buttons are also adequately sized
    cy.get('[data-testid="icon-btn-close"]').should('be.visible');
    cy.get('[data-testid="icon-btn-close"]').then(($icon) => {
      const height = $icon.height();
      const width = $icon.width();
      expect(height).to.be.at.least(44);
      expect(width).to.be.at.least(44);
    });

    // Verify form input fields have adequate height
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').then(($input) => {
      const height = $input.height();
      expect(height).to.be.at.least(44);
    });

    // Test tap interaction on primary button
    cy.get('[data-testid="primary-action-btn"]').click();
    cy.intercept('POST', '/api/action').as('submitAction');
    cy.wait('@submitAction');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should maintain proper spacing between touch targets to prevent accidental taps', () => {
    // Get first and second button elements
    cy.get('[data-testid="button-1"]').should('be.visible');
    cy.get('[data-testid="button-2"]').should('be.visible');

    // Verify minimum spacing between adjacent buttons (8px minimum)
    cy.get('[data-testid="button-1"]').then(($btn1) => {
      cy.get('[data-testid="button-2"]').then(($btn2) => {
        const btn1Bottom = $btn1.offset().top + $btn1.height();
        const btn2Top = $btn2.offset().top;
        const spacing = btn2Top - btn1Bottom;
        expect(spacing).to.be.at.least(8);
      });
    });

    // Verify link elements are not too small
    cy.get('[data-testid="footer-link"]').should('be.visible');
    cy.get('[data-testid="footer-link"]').then(($link) => {
      const height = $link.height();
      const width = $link.width();
      expect(height).to.be.at.least(40);
      expect(width).to.be.at.least(40);
    });

    // Test that small touch targets fail accessibility check
    cy.get('[data-testid="tiny-button"]').should('exist');
    cy.get('[data-testid="tiny-button"]').then(($tiny) => {
      const height = $tiny.height();
      const width = $tiny.width();
      // Assert that this element is too small (negative case)
      expect(height).to.be.below(44);
      expect(width).to.be.below(44);
    });
  });
});

