    await expect(gridContainer).toBeVisible();

    // Verify grid has two-column layout by checking computed style
    const gridStyle = await page.locator('[data-testid="content-grid"]').evaluate(
      (el) => window.getComputedStyle(el).gridTemplateColumns
    );
    expect(gridStyle).toMatch(/\d+px\s+\d+px/);

    // Verify grid items are rendered
    const gridItems = page.locator('[data-testid="grid-item"]');
    const itemCount = await gridItems.count();
    expect(itemCount).toBeGreaterThan(0);

    // Verify first and last grid items are visible
    await expect(gridItems.first()).toBeVisible();
    await expect(gridItems.last()).toBeVisible();

    // Verify desktop sidebar is hidden using getByRole
    const desktopNav = page.getByRole('complementary', { name: /sidebar/i });
    await expect(desktopNav).not.toBeVisible();

    // Verify mobile menu toggle is visible
    const mobileMenuButton = page.getByRole('button', { name: /menu|navigation/i });
    await expect(mobileMenuButton).toBeVisible();

    // Verify grid has proper gap spacing
    const gapStyle = await page.locator('[data-testid="content-grid"]').evaluate(
      (el) => window.getComputedStyle(el).gap
    );
    expect(gapStyle).toBeTruthy();

    // Interact with first grid item
    await gridItems.first().click();
    const detailPanel = page.getByRole('region', { name: /details?/i });
    await expect(detailPanel).toBeVisible();
  });

  test('should revert to single column on narrow mobile viewport', async ({ page }) => {
    // Set narrow mobile viewport
    await page.setViewportSize({ width: 480, height: 800 });

    await page.waitForTimeout(500);

    // Verify grid container is visible using getByRole
    const gridRegion = page.getByRole('main');
    await expect(gridRegion).toBeVisible();

    // Verify grid has single column layout
    const singleColStyle = await page.locator('[data-testid="content-grid"]').evaluate(
      (el) => {
        const style = window.getComputedStyle(el).gridTemplateColumns;
        return style.split(' ').length === 1;
      }
    );
    expect(singleColStyle).toBe(true);

    // Verify grid items exist
    const gridItems = page.locator('[data-testid="grid-item"]');
    const count = await gridItems.count();
