describe('Horizontal Scrolling Disabled on Main Layout - Mobile', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('Happy Path: Main layout should not allow horizontal scrolling on mobile viewport', () => {
    // Verify the main container exists and is visible
    cy.get('[data-testid="main-layout"]').should('be.visible');

    // Get initial horizontal scroll position
    cy.get('[data-testid="main-layout"]').then(($element) => {
      const initialScrollLeft = $element[0].scrollLeft;
      expect(initialScrollLeft).to.equal(0);
    });

    // Attempt to scroll horizontally using keyboard
    cy.get('[data-testid="main-layout"]').focus();
    cy.get('[data-testid="main-layout"]').type('{rightArrow}{rightArrow}{rightArrow}');

    // Verify scroll position hasn't changed
    cy.get('[data-testid="main-layout"]').then(($element) => {
      expect($element[0].scrollLeft).to.equal(0);
    });

    // Verify overflow-x is hidden or auto
    cy.get('[data-testid="main-layout"]').should('have.css', 'overflow-x', 'hidden');

    // Verify body doesn't have horizontal scroll
    cy.get('body').should('have.css', 'overflow-x', 'hidden');

    // Verify no horizontal scrollbar is visible
    cy.window().then((win) => {
      const hasHorizontalScroll = win.document.documentElement.scrollWidth > win.document.documentElement.clientWidth;
      expect(hasHorizontalScroll).to.be.false;
    });
  });

  it('Negative Path: Verify horizontal scrolling is disabled even with wide content', () => {
    // Verify wide content exists within the layout
    cy.get('[data-testid="main-layout"]').should('be.visible');
    cy.get('[data-testid="wide-content"]').should('be.visible');

    // Attempt to swipe/drag horizontally (simulating mobile swipe)
    cy.get('[data-testid="main-layout"]').trigger('touchstart', { touches: [{ clientX: 300 }] });
    cy.get('[data-testid="main-layout"]').trigger('touchmove', { touches: [{ clientX: 100 }] });
    cy.get('[data-testid="main-layout"]').trigger('touchend');

    // Verify scroll position remains at 0
    cy.get('[data-testid="main-layout"]').then(($element) => {
      expect($element[0].scrollLeft).to.equal(0);
    });

    // Verify window scroll position is not affected
    cy.window().then((win) => {
      expect(win.scrollX).to.equal(0);
    });

    // Verify overflow-x property is enforced
    cy.get('[data-testid="main-layout"]').should('have.css', 'overflow-x', 'hidden');

    // Verify no child elements can cause horizontal scroll
    cy.get('[data-testid="main-layout"] > *').each(($child) => {
      cy.wrap($child).should('have.css', 'max-width', '100%');
    });
  });
});

