describe('Bottom Sheet Mobile Dropdown Replacement', () => {
  beforeEach(() => {
    cy.visit('/mobile-form');
    cy.viewport('iphone-x');
  });

  it('should open bottom sheet when clicking dropdown on mobile and select option', () => {
    // Intercept API call for options
    cy.intercept('GET', '/api/dropdown-options').as('fetchOptions');

    // Click the dropdown trigger
    cy.get('[data-testid="country-dropdown"]').click();

    // Wait for API response
    cy.wait('@fetchOptions');

    // Verify bottom sheet is visible
    cy.get('[data-testid="bottom-sheet-overlay"]').should('be.visible');
    cy.get('[data-testid="bottom-sheet-container"]').should('be.visible');

    // Verify header text is present
    cy.get('[data-testid="bottom-sheet-header"]').should('contain', 'Select Country');

    // Verify scroll functionality by checking multiple options are rendered
    cy.get('[data-testid="bottom-sheet-option"]').should('have.length.greaterThan', 3);

    // Select an option by clicking
    cy.get('[data-testid="bottom-sheet-option-USA"]').click();

    // Verify bottom sheet closes after selection
    cy.get('[data-testid="bottom-sheet-overlay"]').should('not.exist');

    // Verify the selected value is displayed in the dropdown field
    cy.get('[data-testid="country-dropdown"]').should('contain', 'USA');

    // Verify selected state in form data
    cy.get('[data-testid="form-country-value"]').should('contain', 'USA');
  });

  it('should handle dismissing bottom sheet without selection and maintain previous value', () => {
    // Set initial value
    cy.get('[data-testid="country-dropdown"]').click();
    cy.get('[data-testid="bottom-sheet-option-Canada"]').click();

    // Verify initial selection
    cy.get('[data-testid="country-dropdown"]').should('contain', 'Canada');

    // Open bottom sheet again
    cy.get('[data-testid="country-dropdown"]').click();
    cy.get('[data-testid="bottom-sheet-overlay"]').should('be.visible');

    // Close by clicking overlay (backdrop dismiss)
    cy.get('[data-testid="bottom-sheet-overlay"]').click({ force: true });

    // Verify bottom sheet is closed
    cy.get('[data-testid="bottom-sheet-container"]').should('not.exist');

    // Verify previous value is maintained
    cy.get('[data-testid="country-dropdown"]').should('contain', 'Canada');

    // Verify form data unchanged
    cy.get('[data-testid="form-country-value"]').should('contain', 'Canada');

    // Verify close button also works
    cy.get('[data-testid="country-dropdown"]').click();
    cy.get('[data-testid="bottom-sheet-close-btn"]').should('be.visible').click();
    cy.get('[data-testid="bottom-sheet-overlay"]').should('not.exist');
  });
});

