    cy.get('[data-testid="bottom-nav-item-profile"]').should('be.visible');
    cy.get('[data-testid="bottom-nav-item-settings"]').should('be.visible');

    // Test navigation still works on mobile
    cy.get('[data-testid="bottom-nav-item-profile"]').click();
    cy.url().should('include', '/profile');
  });

  it('should maintain navigation functionality during viewport resize and handle tablet breakpoint correctly', () => {
    // Start at desktop
    cy.viewport(1280, 720);
    cy.get('[data-testid="sidebar"]').should('be.visible');

    // Intercept API call when navigating
    cy.intercept('GET', '/api/user-profile').as('getUserProfile');

    // Click sidebar navigation
    cy.get('[data-testid="nav-item-profile"]').click();
    cy.wait('@getUserProfile');

    // Resize to tablet (should still show sidebar)
