    // Set initial desktop viewport
    cy.viewport(1920, 1080);

    // Verify video player is visible on desktop
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($player) => {
      const desktopWidth = $player.width();
      const desktopHeight = $player.height();
      expect(desktopWidth).to.be.greaterThan(0);
      expect(desktopHeight).to.be.greaterThan(0);
    });

    // Resize to tablet viewport
