    // Verify video player still visible and resized
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($player) => {
      const tabletWidth = $player.width();
      const tabletHeight = $player.height();
      expect(tabletWidth).to.be.lessThan(1920);
      expect(tabletHeight).to.be.lessThan(1080);
    });

    // Verify aspect ratio is maintained (within tolerance)
    cy.get('[data-testid="video-player"]').then(($player) => {
      const width = $player.width();
      const height = $player.height();
      const aspectRatio = width / height;
      expect(aspectRatio).to.be.closeTo(16 / 9, 0.1);
