    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('John Doe');

    // Mock the payment API to return declined status
    cy.intercept('POST', '/api/payments/process', {
      statusCode: 402,
      body: {
        success: false,
        error: 'Your card was declined. Please try another payment method.',
        errorCode: 'CARD_DECLINED'
      }
    }).as('processPayment');

    // Submit payment
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for API response
    cy.wait('@processPayment');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Your card was declined');

    // Verify error banner styling
    cy.get('[data-testid="error-banner"]')
      .should('have.class', 'error')
      .should('be.visible');

    // Verify submit button is re-enabled
    cy.get('[data-testid="submit-payment-btn"]')
      .should('not.be.disabled');
  });

  it('should handle network error during payment processing', () => {
    // Fill in valid payment form
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('Jane Smith');

    // Mock network failure
    cy.intercept('POST', '/api/payments/process', {
      forceNetworkError: true
    }).as('paymentNetworkError');

    // Attempt to submit payment
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for failed request
    cy.wait('@paymentNetworkError');

    // Verify generic error message
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Unable to process payment');

    // Verify retry button appears
