describe('Apply Promo Code - Payment Flow', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.intercept('GET', '/api/cart').as('getCart');
    cy.intercept('POST', '/api/promo/validate').as('validatePromo');
    cy.intercept('POST', '/api/order/calculate-total').as('calculateTotal');
  });

  it('Happy Path: Apply valid promo code and verify discounted total', () => {
    cy.wait('@getCart');

    cy.get('[data-testid="cart-subtotal"]').should('contain', '$100.00');

    cy.get('[data-testid="promo-code-input"]').should('be.visible').type('SAVE20');

    cy.get('[data-testid="apply-promo-button"]').click();

    cy.wait('@validatePromo').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body.valid).to.equal(true);
      expect(interception.response.body.discountAmount).to.equal(20);
    });

    cy.wait('@calculateTotal');

    cy.get('[data-testid="discount-badge"]').should('be.visible').should('contain', 'SAVE20');

    cy.get('[data-testid="discount-amount"]').should('contain', '-$20.00');

    cy.get('[data-testid="order-total"]').should('contain', '$80.00');

    cy.get('[data-testid="promo-success-message"]').should('be.visible').should('contain', 'Promo code applied successfully');

    cy.get('[data-testid="checkout-button"]').should('be.visible').should('not.be.disabled');
  });

  it('Negative Case: Apply invalid promo code and verify error handling', () => {
    cy.wait('@getCart');

    cy.get('[data-testid="promo-code-input"]').should('be.visible').type('INVALID123');

    cy.get('[data-testid="apply-promo-button"]').click();

    cy.wait('@validatePromo').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body.valid).to.equal(false);
      expect(interception.response.body.error).to.include('Promo code not found');
    });

    cy.get('[data-testid="promo-error-message"]').should('be.visible').should('contain', 'Invalid or expired promo code');

    cy.get('[data-testid="discount-badge"]').should('not.exist');

    cy.get('[data-testid="order-total"]').should('contain', '$100.00');

    cy.get('[data-testid="promo-code-input"]').should('have.value', 'INVALID123');

    cy.get('[data-testid="apply-promo-button"]').should('be.visible').should('not.be.disabled');
  });
});

