    await page.route('**/api/promo-codes/validate', (route) => {
      requestCount++;
      if (requestCount === 1) {
        route.abort('failed');
      } else {
        route.continue();
      }
    });

    // Act: First attempt with expired code using getByLabel
    const promoInput = page.getByLabel('Promo Code');
    await expect(promoInput).toBeVisible();
    await promoInput.fill('EXPIRED2023');

