describe('Payment Timeout Error Page Redirect', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should redirect to error page when payment times out', () => {
    // Setup intercept to simulate timeout
    cy.intercept('POST', '/api/v1/payment/process', (req) => {
      req.reply((res) => {
        res.delay(35000); // Simulate timeout delay
        res.send({
          statusCode: 504,
          body: { error: 'Payment processing timeout' }
        });
      });
    }).as('paymentTimeout');

    // User fills in payment details
    cy.get('[data-testid="card-number-input"]').type('4242424242424242');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvv-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('John Doe');

    // User submits payment
    cy.get('[data-testid="pay-button"]').click();

    // Wait for timeout response
    cy.wait('@paymentTimeout');

    // Assert redirect to error page
    cy.url().should('include', '/payment-error');
    cy.get('[data-testid="error-title"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Payment processing timed out');
    cy.get('[data-testid="error-code"]').should('contain', '504');
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });

  it('should display timeout error message and allow retry when payment fails to respond', () => {
    // Setup intercept with network error simulation
    cy.intercept('POST', '/api/v1/payment/process', {
      forceNetworkError: true
    }).as('paymentNetworkError');

    // User enters payment information
    cy.get('[data-testid="card-number-input"]').type('5555555555554444');
    cy.get('[data-testid="card-expiry-input"]').type('06/26');
    cy.get('[data-testid="card-cvv-input"]').type('456');
    cy.get('[data-testid="cardholder-name-input"]').type('Jane Smith');

    // User clicks pay button
    cy.get('[data-testid="pay-button"]').click();

    // Wait for network error
    cy.wait('@paymentNetworkError');

    // Verify error page is displayed
    cy.url().should('include', '/payment-error');
    cy.get('[data-testid="error-title"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', 'Payment Failed');
    cy.get('[data-testid="error-description"]').should('contain', 'timeout');

    // Verify retry action is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="back-to-checkout"]').should('be.visible');
    cy.get('[data-testid="contact-support"]').should('not.exist');
