    // Verify the page content is still visible and functional
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should handle dismissal of multiple notifications in sequence', () => {
    // Intercept notification creation API call
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify first notification is visible
    cy.get('[data-testid="notification-container"]').first().should('be.visible');
    cy.get('[data-testid="notification-message"]').first().should('contain', 'Operation completed successfully');

