    cy.get('[data-testid="notification-container"]').should('have.length', 1);
    cy.get('[data-testid="notification-message"]').should('contain', 'Warning: Check your settings');

    // Dismiss the second notification
    cy.get('[data-testid="notification-close-btn"]').click();

