describe('Mark All Notifications as Read', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should mark all notifications as read with one click - happy path', () => {
    // Setup: Intercept API call to fetch notifications
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          { id: 1, title: 'New message', read: false },
          { id: 2, title: 'Comment reply', read: false },
          { id: 3, title: 'System update', read: false },
        ],
      },
    }).as('getNotifications');

    cy.wait('@getNotifications');

    // Verify unread notifications are visible
    cy.get('[data-testid="notification-item"]').should('have.length', 3);
    cy.get('[data-testid="notification-unread-badge"]').should('be.visible');
    cy.get('[data-testid="notification-unread-badge"]').should('contain', '3');

    // Intercept the mark all as read API call
    cy.intercept('PATCH', '/api/notifications/mark-all-read', {
      statusCode: 200,
      body: { success: true, markedCount: 3 },
    }).as('markAllRead');

    // Click the "Mark All as Read" button
    cy.get('[data-testid="mark-all-read-button"]').click();

    // Wait for API response
    cy.wait('@markAllRead');

    // Verify all notifications are now marked as read
    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).should('have.class', 'read');
    });

    // Verify unread badge is gone or shows 0
    cy.get('[data-testid="notification-unread-badge"]').should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'All notifications marked as read');
  });

  it('should handle edge case when no unread notifications exist', () => {
    // Setup: Intercept API call with no unread notifications
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          { id: 1, title: 'Old message', read: true },
          { id: 2, title: 'Old reply', read: true },
        ],
      },
    }).as('getNotifications');

    cy.wait('@getNotifications');

    // Verify unread badge does not exist
    cy.get('[data-testid="notification-unread-badge"]').should('not.exist');

    // Verify all notifications show as read
    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).should('have.class', 'read');
    });

    // "Mark All as Read" button should be disabled when no unread notifications
    cy.get('[data-testid="mark-all-read-button"]').should('be.disabled');

    // Attempt to click disabled button should not trigger API call
    cy.intercept('PATCH', '/api/notifications/mark-all-read').as('markAllRead');
    cy.get('[data-testid="mark-all-read-button"]').click();
    cy.get('@markAllRead.all').then((interceptions) => {
      expect(interceptions).to.have.length(0);
    });

    // Verify info message about no unread notifications
    cy.get('[data-testid="info-message"]').should('be.visible');
    cy.get('[data-testid="info-message"]').should('contain', 'No unread notifications');
  });
});

