    await expect(emptyStateDescription).toBeVisible();

    const notificationsList = page.getByTestId('notifications-list');
    await expect(notificationsList).not.toBeVisible();
  });

  test('should handle API error gracefully and show fallback empty state with retry', async ({ page }) => {
    await page.route('**/api/notifications', (route) => {
      route.abort('failed');
    });

    await page.goto('/notifications');

    const emptyStateContainer = page.getByTestId('empty-state-container');
