describe('Browser Push Notifications for Urgent Alerts', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.intercept('POST', '/api/notifications/subscribe').as('subscribeNotification');
    cy.intercept('GET', '/api/alerts').as('fetchAlerts');
  });

  it('should enable push notifications and receive urgent alert', () => {
    // Grant notification permission
    cy.window().then((win) => {
      cy.stub(win.Notification, 'requestPermission').resolves('granted');
    });

    // Click enable notifications button
    cy.get('[data-testid="enable-notifications-btn"]').click();
    cy.wait('@subscribeNotification');

    // Verify subscription confirmation message
    cy.get('[data-testid="notification-status"]').should('contain', 'Notifications enabled');

    // Simulate urgent alert push notification
    cy.get('[data-testid="send-test-alert-btn"]').click();
    cy.wait('@fetchAlerts');

    // Verify notification appears in UI
    cy.get('[data-testid="alert-notification"]').should('be.visible');
    cy.get('[data-testid="alert-notification"]').should('contain', 'URGENT');

    // Verify notification content
    cy.get('[data-testid="alert-title"]').should('contain', 'Urgent Alert');
    cy.get('[data-testid="alert-message"]').should('contain', 'Immediate action required');

    // Click dismiss on notification
    cy.get('[data-testid="dismiss-notification-btn"]').click();
    cy.get('[data-testid="alert-notification"]').should('not.exist');
  });

  it('should handle denied notification permission and show fallback', () => {
    // Deny notification permission
    cy.window().then((win) => {
      cy.stub(win.Notification, 'requestPermission').resolves('denied');
    });

    // Click enable notifications button
    cy.get('[data-testid="enable-notifications-btn"]').click();

    // Verify error/fallback message
    cy.get('[data-testid="notification-status"]').should('contain', 'Notifications disabled');

    // Verify in-app alert badge appears instead
    cy.get('[data-testid="alert-badge"]').should('be.visible');
    cy.get('[data-testid="alert-count"]').should('contain', '1');

    // Click on badge to view alert
    cy.get('[data-testid="alert-badge"]').click();

    // Verify in-app alert panel opens
    cy.get('[data-testid="alert-panel"]').should('be.visible');
    cy.get('[data-testid="alert-item"]').should('contain', 'Urgent Alert');

    // Verify action button is available
    cy.get('[data-testid="alert-action-btn"]').should('be.visible');
    cy.get('[data-testid="alert-action-btn"]').click();
    cy.get('[data-testid="alert-panel"]').should('not.exist');
  });
});

