import { test, expect } from '@playwright/test';

test.describe('Browser Push Notifications for Urgent Alerts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
    await page.routeFromHAR('./notifications.har', { url: '**/api/**', update: false });
  });

  test('should enable push notifications and receive urgent alert', async ({ page, context }) => {
    // Grant notification permission at browser context level
    await context.grantPermissions(['notifications']);

    // Get enable notifications button and click it
    const enableBtn = page.getByRole('button', { name: /enable.*notification/i });
    await expect(enableBtn).toBeVisible();
    await enableBtn.click();

    // Wait for subscription to complete
    await page.waitForResponse(response => response.url().includes('/api/notifications/subscribe'));

    // Verify subscription success message
    const statusMessage = page.getByLabel('notification-status');
    await expect(statusMessage).toContainText('Notifications enabled');

    // Send test alert
    const testAlertBtn = page.getByRole('button', { name: /send.*test.*alert/i });
    await expect(testAlertBtn).toBeVisible();
    await testAlertBtn.click();

    // Wait for alerts endpoint
    await page.waitForResponse(response => response.url().includes('/api/alerts'));

    // Verify notification appears in UI
    const alertNotification = page.getByLabel('alert-notification');
    await expect(alertNotification).toBeVisible();
    await expect(alertNotification).toContainText('URGENT');

    // Verify notification details
    const alertTitle = page.getByText('Urgent Alert');
    await expect(alertTitle).toBeVisible();

    const alertMessage = page.getByText('Immediate action required');
    await expect(alertMessage).toBeVisible();

    // Dismiss notification
    const dismissBtn = page.getByRole('button', { name: /dismiss/i });
    await dismissBtn.click();

    // Verify notification is removed
    await expect(alertNotification).not.toBeVisible();
  });

  test('should handle denied notification permission and show fallback alert', async ({ page, context }) => {
    // Deny notification permission
    await context.clearPermissions();

    // Click enable notifications button
    const enableBtn = page.getByRole('button', { name: /enable.*notification/i });
    await enableBtn.click();

    // Verify fallback message appears
    const statusMessage = page.getByText('Notifications disabled');
    await expect(statusMessage).toBeVisible();

    // Verify in-app alert badge is visible
    const alertBadge = page.getByLabel('alert-badge');
    await expect(alertBadge).toBeVisible();

    // Verify alert count badge
    const alertCount = page.getByText('1');
    await expect(alertCount).toBeVisible();

    // Click badge to open in-app alerts panel
    await alertBadge.click();

    // Verify alert panel opened
    const alertPanel = page.getByRole('region', { name: /alert.*panel/i });
    await expect(alertPanel).toBeVisible();

    // Verify alert content
    const alertItem = page.getByText('Urgent Alert');
    await expect(alertItem).toBeVisible();

    // Click action button on alert
    const actionBtn = page.getByRole('button', { name: /acknowledge|view|action/i });
    await expect(actionBtn).toBeVisible();
    await actionBtn.click();

    // Verify panel closes
    await expect(alertPanel).not.toBeVisible();
  });
});

