describe('Notification Filter by Type', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.intercept('GET', '/api/notifications?type=*').as('filterNotifications');
    cy.wait('@getNotifications');
  });

  it('should filter notifications by type - happy path', () => {
    // Verify all notifications are displayed initially
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Click on Info filter button
    cy.get('[data-testid="filter-type-info"]').click();
    cy.wait('@filterNotifications');

    // Verify only info notifications are visible
    cy.get('[data-testid="notification-item"]').each(($el) => {
      cy.wrap($el).should('contain', 'info');
    });

    // Click on Warning filter button
    cy.get('[data-testid="filter-type-warning"]').click();
    cy.wait('@filterNotifications');

    // Verify only warning notifications are visible
    cy.get('[data-testid="notification-item"]').each(($el) => {
      cy.wrap($el).should('contain', 'warning');
    });

    // Click on Error filter button
    cy.get('[data-testid="filter-type-error"]').click();
    cy.wait('@filterNotifications');

    // Verify only error notifications are visible
    cy.get('[data-testid="notification-item"]').each(($el) => {
      cy.wrap($el).should('contain', 'error');
    });

    // Click Clear Filters button to reset
    cy.get('[data-testid="clear-filters-btn"]').click();
    cy.wait('@getNotifications');

    // Verify all notifications are displayed again
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
  });

  it('should handle edge case - no notifications for selected filter type', () => {
    // Apply filter for a type that might have no notifications
    cy.get('[data-testid="filter-type-info"]').click();
    cy.wait('@filterNotifications');

    // Check if empty state message is displayed or no items exist
    cy.get('[data-testid="notification-item"]').then(($items) => {
      if ($items.length === 0) {
        cy.get('[data-testid="empty-state-message"]')
          .should('be.visible')
          .should('contain', 'No notifications');
      }
    });

    // Verify filter badge is still active
    cy.get('[data-testid="filter-type-info"]').should('have.class', 'active');

    // Apply another filter type
    cy.get('[data-testid="filter-type-warning"]').click();
    cy.wait('@filterNotifications');

    // Verify previous filter is deselected if single-select behavior
    cy.get('[data-testid="notification-item"]').should('exist');
  });
});

