import { test, expect } from '@playwright/test';

test.describe('Notification Filter by Type', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
    await page.waitForLoadState('networkidle');
  });

  test('should filter notifications by type - happy path', async ({ page }) => {
    // Verify initial state with all notifications
    const allNotifications = page.getByRole('listitem', { name: /notification/i });
    await expect(allNotifications).toHaveCount(await allNotifications.count());
    const initialCount = await allNotifications.count();
    expect(initialCount).toBeGreaterThan(0);

    // Click Info filter button using getByRole
    const infoFilterBtn = page.getByRole('button', { name: /info/i });
    await infoFilterBtn.click();
    await page.waitForLoadState('networkidle');

    // Verify only info type notifications appear
    const infoNotifications = page.getByRole('listitem');
    const infoCount = await infoNotifications.count();
    for (let i = 0; i < infoCount; i++) {
      await expect(infoNotifications.nth(i)).toContainText(/info/i);
    }

    // Click Warning filter button using getByRole
    const warningFilterBtn = page.getByRole('button', { name: /warning/i });
    await warningFilterBtn.click();
    await page.waitForLoadState('networkidle');

    // Verify only warning type notifications appear
    const warningNotifications = page.getByRole('listitem');
    const warningCount = await warningNotifications.count();
    for (let i = 0; i < warningCount; i++) {
      await expect(warningNotifications.nth(i)).toContainText(/warning/i);
    }

    // Click Error filter button using getByRole
    const errorFilterBtn = page.getByRole('button', { name: /error/i });
    await errorFilterBtn.click();
    await page.waitForLoadState('networkidle');

    // Verify only error type notifications appear
    const errorNotifications = page.getByRole('listitem');
    const errorCount = await errorNotifications.count();
    for (let i = 0; i < errorCount; i++) {
      await expect(errorNotifications.nth(i)).toContainText(/error/i);
    }

    // Click Clear Filters button to reset
    const clearFiltersBtn = page.getByRole('button', { name: /clear filters/i });
    await clearFiltersBtn.click();
    await page.waitForLoadState('networkidle');

    // Verify all notifications are displayed again
    const resetNotifications = page.getByRole('listitem');
    const resetCount = await resetNotifications.count();
    expect(resetCount).toBeGreaterThan(0);
  });

  test('should handle edge case - no notifications for selected filter type', async ({ page }) => {
    // Apply Info filter
    const infoFilterBtn = page.getByRole('button', { name: /info/i });
    await infoFilterBtn.click();
    await page.waitForLoadState('networkidle');

    // Check for empty state or no items
    const notificationItems = page.getByRole('listitem');
    const itemCount = await notificationItems.count();

    if (itemCount === 0) {
      // Verify empty state message is displayed
      const emptyMessage = page.getByText(/no notifications/i);
      await expect(emptyMessage).toBeVisible();
    }

    // Verify filter button shows active state
    const activeFilterBtn = page.getByRole('button', { name: /info/i });
    const activeClass = await activeFilterBtn.getAttribute('class');
    expect(activeClass).toContain('active');

    // Switch to Warning filter
    const warningFilterBtn = page.getByRole('button', { name: /warning/i });
    await warningFilterBtn.click();
    await page.waitForLoadState('networkidle');

    // Verify the filter switched successfully
    const warningActiveBtn = page.getByRole('button', { name: /warning/i });
    const warningActiveClass = await warningActiveBtn.getAttribute('class');
    expect(warningActiveClass).toContain('active');

    // Verify notification list is updated or shows empty state
    const updatedItems = page.getByRole('listitem');
    await expect(updatedItems).toHaveCount(await updatedItems.count());
  });
});

