describe('Notification Panel Slide-In Feature', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display notification panel sliding in from the top when triggered', () => {
    // Verify the notification panel is initially hidden
    cy.get('[data-testid="notification-panel"]').should('not.exist');

    // Trigger the notification by clicking the button
    cy.get('[data-testid="trigger-notification-btn"]').click();

    // Wait for notification API call
    cy.intercept('POST', '/api/notifications/trigger').as('notificationTriggered');
    cy.wait('@notificationTriggered');

    // Verify notification panel is now visible
    cy.get('[data-testid="notification-panel"]').should('be.visible');

    // Verify panel has slide-in animation class
    cy.get('[data-testid="notification-panel"]').should('have.class', 'slide-in-top');

    // Verify notification content is displayed correctly
    cy.get('[data-testid="notification-message"]').should('contain', 'Notification received');

    // Verify close button is accessible
    cy.get('[data-testid="notification-close-btn"]').should('be.visible');

    // Verify notification panel is positioned at the top
    cy.get('[data-testid="notification-panel"]').should('have.css', 'position', 'fixed');
  });

  it('should handle rapid notification triggers and edge case when panel fails to appear', () => {
    // Attempt to trigger notification with API failure
    cy.intercept('POST', '/api/notifications/trigger', { statusCode: 500 }).as('notificationError');

    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.wait('@notificationError');

    // Verify error state is handled gracefully
    cy.get('[data-testid="notification-panel"]').should('not.exist');

    // Verify error message is shown instead
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to display notification');

    // Trigger multiple notifications rapidly
    cy.intercept('POST', '/api/notifications/trigger').as('notificationSuccess');

    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.wait('@notificationSuccess');

    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.wait('@notificationSuccess');

    // Verify only the latest notification panel is visible
    cy.get('[data-testid="notification-panel"]').should('have.length', 1);
    cy.get('[data-testid="notification-panel"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Notification Panel Slide-In Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display notification panel sliding in from the top when triggered', async ({ page }) => {
    // Verify the notification panel is initially hidden
    const notificationPanel = page.locator('[data-testid="notification-panel"]');
    await expect(notificationPanel).not.toBeVisible();

    // Get the trigger button using getByRole
    const triggerButton = page.getByRole('button', { name: /trigger notification/i });
    await expect(triggerButton).toBeVisible();

    // Trigger the notification by clicking the button
    await triggerButton.click();

    // Wait for notification API call
    await page.waitForResponse(response => 
      response.url().includes('/api/notifications/trigger') && response.status() === 200
    );

    // Verify notification panel is now visible
    await expect(notificationPanel).toBeVisible();

    // Verify panel has slide-in animation class
    const panelClass = await notificationPanel.getAttribute('class');
    expect(panelClass).toContain('slide-in-top');

    // Verify notification content is displayed correctly
    const notificationMessage = page.getByText(/Notification received/);
    await expect(notificationMessage).toBeVisible();

    // Verify close button is accessible using getByRole
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify notification panel is positioned at the top
    const panelStyle = await notificationPanel.getAttribute('style');
    expect(panelStyle).toContain('position: fixed');
  });

  test('should handle rapid notification triggers and edge case when panel fails to appear', async ({ page }) => {
    // Set up API failure response
    await page.route('/api/notifications/trigger', route => {
      route.abort('failed');
    });

    // Get the trigger button
    const triggerButton = page.getByRole('button', { name: /trigger notification/i });
    await triggerButton.click();

    // Small delay for error state to be processed
    await page.waitForTimeout(500);

    // Verify notification panel is not shown on failure
    const notificationPanel = page.locator('[data-testid="notification-panel"]');
    await expect(notificationPanel).not.toBeVisible();

    // Verify error message is shown instead using getByText
    const errorMessage = page.getByText(/Failed to display notification/);
    await expect(errorMessage).toBeVisible();

    // Clear route and restore successful API responses
    await page.unroute('/api/notifications/trigger');

    // Trigger multiple notifications rapidly
    await triggerButton.click();
    await page.waitForResponse(response => 
      response.url().includes('/api/notifications/trigger') && response.status() === 200
    );

    await triggerButton.click();
    await page.waitForResponse(response => 
      response.url().includes('/api/notifications/trigger') && response.status() === 200
    );

    // Small delay to ensure panels render
    await page.waitForTimeout(300);

    // Verify only the latest notification panel is visible
    const panelCount = await page.locator('[data-testid="notification-panel"]').count();
    expect(panelCount).toBeLessThanOrEqual(1);

    const visiblePanel = page.locator('[data-testid="notification-panel"]:visible');
    await expect(visiblePanel).toBeVisible();
  });
});

