describe('Unread Notifications Visual Distinction', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');
  });

  it('should display unread notifications with distinct visual styling', () => {
    cy.get('[data-testid="notification-item"]').first().within(() => {
      cy.get('[data-testid="unread-indicator"]').should('be.visible');
      cy.get('[data-testid="notification-badge"]').should('have.css', 'background-color', 'rgb(59, 130, 246)');
      cy.get('[data-testid="notification-text"]').should('have.css', 'font-weight', '700');
    });

    cy.get('[data-testid="notification-item"]').eq(1).within(() => {
      cy.get('[data-testid="read-indicator"]').should('be.visible');
      cy.get('[data-testid="notification-badge"]').should('have.css', 'background-color', 'rgb(209, 213, 219)');
      cy.get('[data-testid="notification-text"]').should('have.css', 'font-weight', '400');
    });

    cy.get('[data-testid="unread-count"]').should('contain', '1');
  });

  it('should update visual styling when marking notification as read', () => {
    cy.get('[data-testid="notification-item"]').first().within(() => {
      cy.get('[data-testid="unread-indicator"]').should('be.visible');
      cy.get('[data-testid="notification-badge"]').should('have.css', 'background-color', 'rgb(59, 130, 246)');
    });

    cy.intercept('PATCH', '/api/notifications/*/read').as('markAsRead');

    cy.get('[data-testid="notification-item"]').first().click();
    cy.wait('@markAsRead');

    cy.get('[data-testid="notification-item"]').first().within(() => {
      cy.get('[data-testid="unread-indicator"]').should('not.exist');
      cy.get('[data-testid="notification-badge"]').should('have.css', 'background-color', 'rgb(209, 213, 219)');
      cy.get('[data-testid="notification-text"]').should('have.css', 'font-weight', '400');
    });

    cy.get('[data-testid="unread-count"]').should('contain', '0');
  });
});

