import { test, expect } from '@playwright/test';

test.describe('Unread Notifications Visual Distinction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
    await page.waitForLoadState('networkidle');
  });

  test('should display unread notifications with distinct visual styling', async ({ page }) => {
    const notificationItems = page.getByRole('listitem').filter({ hasText: /unread|new/ });
    const unreadBadge = page.getByRole('status', { name: /unread/i });

    await expect(unreadBadge).toBeVisible();

    const firstUnreadNotification = notificationItems.first();
    const unreadIndicator = firstUnreadNotification.locator('[data-testid="unread-indicator"]');

    await expect(unreadIndicator).toBeVisible();

    const notificationText = firstUnreadNotification.getByRole('heading', { level: 3 });
    const fontWeightValue = await notificationText.evaluate((el) => window.getComputedStyle(el).fontWeight);
    expect(fontWeightValue).toBe('700');

    const notificationBg = firstUnreadNotification.locator('[data-testid="notification-badge"]');
    const bgColor = await notificationBg.evaluate((el) => window.getComputedStyle(el).backgroundColor);
    expect(bgColor).toBe('rgb(59, 130, 246)');

    const readNotification = notificationItems.last();
    const readIndicator = readNotification.locator('[data-testid="read-indicator"]');
    await expect(readIndicator).toBeVisible();
  });

  test('should update visual styling when marking notification as read', async ({ page }) => {
    const unreadButton = page.getByRole('button', { name: /mark as read|read/i });
    const notificationItem = page.getByRole('listitem').filter({ hasText: /unread/ }).first();

    const initialUnreadCount = page.getByLabel(/unread count|notifications pending/i);
    await expect(initialUnreadCount).toContainText(/[1-9]/);

    await notificationItem.click();
    await page.waitForLoadState('networkidle');

    const unreadIndicator = notificationItem.locator('[data-testid="unread-indicator"]');
    await expect(unreadIndicator).not.toBeVisible();

    const notificationBg = notificationItem.locator('[data-testid="notification-badge"]');
