      route.continue({
        status: 200,
        body: JSON.stringify({
          notifications: [
            {
              id: '1',
              message: 'New message received',
              type: 'info',
              timestamp: new Date().toISOString()
            }
          ]
        })
      });
    });

    // Click send message button using getByRole
    const sendButton = page.getByRole('button', { name: /send message/i });
    await expect(sendButton).toBeVisible();
    await sendButton.click();

    // Wait for notification to appear
    const notificationItem = page.getByText('New message received');
    await expect(notificationItem).toBeVisible();

    // Verify notification content
    await expect(notificationItem).toContainText('New message received');

    // Verify and interact with close button using getByRole
    const closeButton = page.getByRole('button', { name: /close|dismiss/i });
    await expect(closeButton).toBeVisible();
    await closeButton.click();

    // Verify notification is removed
    await expect(notificationItem).not.toBeVisible();
