describe('Dark Mode Toggle in User Preferences', () => {
  beforeEach(() => {
    cy.visit('/preferences');
  });

  it('should successfully toggle dark mode on and persist the setting', () => {
    // Verify the preferences page loads
    cy.get('[data-testid="preferences-page"]').should('be.visible');

    // Check initial state - assume light mode is default
    cy.get('[data-testid="dark-mode-toggle"]').should('not.be.checked');
    cy.get('body').should('not.have.class', 'dark-mode');

    // Intercept the API call to save preferences
    cy.intercept('PATCH', '/api/user/preferences').as('updatePreferences');

    // Click the dark mode toggle
    cy.get('[data-testid="dark-mode-toggle"]').click();

    // Verify toggle is now checked
    cy.get('[data-testid="dark-mode-toggle"]').should('be.checked');

    // Verify dark mode class is applied to body
    cy.get('body').should('have.class', 'dark-mode');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Preferences updated');

    // Wait for the API call to complete
    cy.wait('@updatePreferences').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.request.body).to.include('darkMode');
    });

    // Reload page to verify persistence
    cy.reload();
    cy.get('[data-testid="dark-mode-toggle"]').should('be.checked');
    cy.get('body').should('have.class', 'dark-mode');
  });

  it('should handle API failure gracefully when toggling dark mode', () => {
    // Verify the preferences page loads
    cy.get('[data-testid="preferences-page"]').should('be.visible');

    // Intercept the API call and simulate failure
    cy.intercept('PATCH', '/api/user/preferences', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('updatePreferencesFailed');

    // Click the dark mode toggle
    cy.get('[data-testid="dark-mode-toggle"]').click();

    // Wait for the failed API call
    cy.wait('@updatePreferencesFailed');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to update preferences');

    // Verify toggle reverts to unchecked state after failure
    cy.get('[data-testid="dark-mode-toggle"]').should('not.be.checked');

    // Verify dark mode class is not applied
    cy.get('body').should('not.have.class', 'dark-mode');
  });
});

