import { test, expect } from '@playwright/test';

test.describe('Dark Mode Toggle in User Preferences', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/preferences');
  });

  test('should successfully toggle dark mode on and persist the setting', async ({ page }) => {
    // Verify the preferences page loads
    const preferencesPage = page.getByRole('main');
    await expect(preferencesPage).toBeVisible();

    // Get the dark mode toggle by label
    const darkModeToggle = page.getByLabel('Dark Mode');
    await expect(darkModeToggle).toBeVisible();

    // Check initial state - assume light mode is default
    await expect(darkModeToggle).not.toBeChecked();

    // Get the body element to check class
    const bodyElement = page.locator('body');
    await expect(bodyElement).not.toHaveClass(/dark-mode/);

    // Intercept the API call to save preferences
    await page.route('**/api/user/preferences', async (route) => {
      await route.continue({
        status: 200,
        body: JSON.stringify({ success: true, darkMode: true })
      });
    });

    // Click the dark mode toggle
    await darkModeToggle.click();

    // Verify toggle is now checked
    await expect(darkModeToggle).toBeChecked();

    // Verify dark mode class is applied to body
    await expect(bodyElement).toHaveClass(/dark-mode/);

    // Verify success message appears
    const successMessage = page.getByRole('status');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('Preferences updated');

    // Reload page to verify persistence
    await page.reload();
    await expect(darkModeToggle).toBeChecked();
    await expect(bodyElement).toHaveClass(/dark-mode/);
  });

  test('should handle API failure gracefully when toggling dark mode', async ({ page }) => {
    // Verify the preferences page loads
    const preferencesPage = page.getByRole('main');
    await expect(preferencesPage).toBeVisible();

    // Get the dark mode toggle by label
    const darkModeToggle = page.getByLabel('Dark Mode');
    await expect(darkModeToggle).toBeVisible();

    // Intercept the API call and simulate failure
    await page.route('**/api/user/preferences', async (route) => {
      await route.abort('failed');
    });

    // Click the dark mode toggle
    await darkModeToggle.click();

    // Wait a moment for the error handling to complete
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Failed to update preferences');

    // Verify toggle reverts to unchecked state after failure
    await expect(darkModeToggle).not.toBeChecked();

    // Verify dark mode class is not applied
    const bodyElement = page.locator('body');
    await expect(bodyElement).not.toHaveClass(/dark-mode/);
  });
});

