describe('User Timezone Settings in Profile', () => {
  beforeEach(() => {
    cy.visit('/profile/settings');
  });

  it('should successfully set timezone to a valid option', () => {
    // Intercept the timezone update API
    cy.intercept('PUT', '/api/profile/timezone').as('updateTimezone');

    // Navigate to timezone section
    cy.get('[data-testid="profile-settings-nav"]').click();
    cy.get('[data-testid="timezone-section"]').should('be.visible');

    // Open timezone dropdown
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-option-pst"]').should('be.visible');

    // Select PST timezone
    cy.get('[data-testid="timezone-option-pst"]').click();

    // Verify selection is displayed
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'Pacific Standard Time');

    // Click save button
    cy.get('[data-testid="save-timezone-btn"]').click();

    // Wait for API response
    cy.wait('@updateTimezone').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.request.body.timezone).to.equal('America/Los_Angeles');
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Timezone updated successfully');

    // Verify timezone persists after page reload
    cy.reload();
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'Pacific Standard Time');
  });

  it('should display validation error when attempting to save without selecting a timezone', () => {
    // Navigate to timezone section
    cy.get('[data-testid="profile-settings-nav"]').click();
    cy.get('[data-testid="timezone-section"]').should('be.visible');

    // Verify timezone dropdown has no selection
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'Select a timezone');

    // Attempt to save without making a selection
    cy.get('[data-testid="save-timezone-btn"]').click();

    // Verify error message appears
    cy.get('[data-testid="timezone-error"]').should('be.visible');
    cy.get('[data-testid="timezone-error"]').should('contain', 'Timezone selection is required');

    // Verify save button remains enabled for retry
    cy.get('[data-testid="save-timezone-btn"]').should('not.be.disabled');

    // Verify no API call was made
    cy.intercept('PUT', '/api/profile/timezone').as('updateTimezoneAttempt');
    cy.get('[data-testid="save-timezone-btn"]').click();
    cy.get('@updateTimezoneAttempt.all').should('have.length', 0);
  });
});

