describe('Delete Account Feature', () => {
  beforeEach(() => {
    cy.visit('/account/settings');
  });

  it('should delete account successfully when correct password is provided', () => {
    cy.get('[data-testid="delete-account-button"]').click();
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
    cy.get('[data-testid="password-input"]').type('correct-password-123');
    cy.intercept('POST', '/api/account/delete').as('deleteAccount');
    cy.get('[data-testid="confirm-delete-button"]').click();
    cy.wait('@deleteAccount').its('response.statusCode').should('equal', 200);
    cy.url().should('include', '/login');
    cy.get('[data-testid="success-message"]').should('contain', 'Account deleted successfully');
  });

  it('should display error when incorrect password is provided', () => {
    cy.get('[data-testid="delete-account-button"]').click();
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
    cy.get('[data-testid="password-input"]').type('wrong-password-456');
    cy.intercept('POST', '/api/account/delete').as('deleteAccount');
    cy.get('[data-testid="confirm-delete-button"]').click();
    cy.wait('@deleteAccount').its('response.statusCode').should('equal', 401);
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Incorrect password');
    cy.url().should('include', '/account/settings');
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
  });
