import { test, expect } from '@playwright/test';

test.describe('Delete Account Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/account/settings');
  });

  test('should delete account successfully when correct password is provided', async ({ page }) => {
    const deleteButton = page.getByRole('button', { name: 'Delete Account' });
    await deleteButton.click();

    const modal = page.getByRole('dialog', { name: 'Delete Account Confirmation' });
    await expect(modal).toBeVisible();

    const passwordInput = page.getByLabel('Enter your password');
    await passwordInput.fill('correct-password-123');

    await page.route('**/api/account/delete', route => {
      route.abort();
    });

    const confirmButton = page.getByRole('button', { name: 'Confirm Delete' });
    await confirmButton.click();

    await page.waitForURL('**/login');
    const successMessage = page.getByText('Account deleted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should display error when incorrect password is provided', async ({ page }) => {
    const deleteButton = page.getByRole('button', { name: 'Delete Account' });
    await deleteButton.click();

    const modal = page.getByRole('dialog', { name: 'Delete Account Confirmation' });
    await expect(modal).toBeVisible();

    const passwordInput = page.getByLabel('Enter your password');
    await passwordInput.fill('wrong-password-456');

    page.on('response', response => {
      if (response.url().includes('/api/account/delete')) {
        expect(response.status()).toBe(401);
      }
    });

    const confirmButton = page.getByRole('button', { name: 'Confirm Delete' });
    await confirmButton.click();

    const errorMessage = page.getByText('Incorrect password');
    await expect(errorMessage).toBeVisible();

    await expect(page).toHaveURL('**/account/settings');
    await expect(modal).toBeVisible();
  });
});

