describe('Public User Profile Page', () => {
  beforeEach(() => {
    cy.visit('/profile/public');
  });

  it('should display public profile with shared user information', () => {
    // Intercept API call to fetch user profile data
    cy.intercept('GET', '/api/users/*/profile/public').as('getPublicProfile');

    // Wait for profile data to load
    cy.wait('@getPublicProfile');

    // Verify profile header is visible
    cy.get('[data-testid="profile-header"]').should('be.visible');

    // Verify username is displayed
    cy.get('[data-testid="username"]').should('be.visible').should('contain', 'john_doe');

    // Verify profile image is visible
    cy.get('[data-testid="profile-avatar"]').should('be.visible');

    // Verify bio/description section
    cy.get('[data-testid="profile-bio"]').should('be.visible').should('contain', 'Software Engineer');

    // Verify social links are displayed
    cy.get('[data-testid="social-links"]').should('be.visible');
    cy.get('[data-testid="github-link"]').should('have.attr', 'href');
    cy.get('[data-testid="linkedin-link"]').should('have.attr', 'href');

    // Verify shared projects/portfolio section
    cy.get('[data-testid="shared-projects"]').should('be.visible');
    cy.get('[data-testid="project-card"]').should('have.length.greaterThan', 0);

    // Verify followers count is visible
    cy.get('[data-testid="followers-count"]').should('be.visible').should('contain', 'Followers');

    // Verify follow button is available
    cy.get('[data-testid="follow-button"]').should('be.visible').should('not.be.disabled');

    // Verify last updated timestamp
    cy.get('[data-testid="last-updated"]').should('be.visible');
  });

  it('should handle missing or private profile gracefully', () => {
    // Intercept API with 404 error response
    cy.intercept('GET', '/api/users/*/profile/public', {
      statusCode: 404,
      body: { error: 'Profile not found' }
    }).as('profileNotFound');

    cy.reload();
    cy.wait('@profileNotFound');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Profile not found');

    // Verify profile content is not visible
    cy.get('[data-testid="profile-header"]').should('not.exist');
    cy.get('[data-testid="username"]').should('not.exist');

    // Verify fallback UI or error recovery button is shown
    cy.get('[data-testid="go-back-button"]').should('be.visible').click();

    // Verify navigation occurred
    cy.url().should('not.include', '/profile/public');
  });
});

