describe('Google Account Connection - User Profile', () => {
  beforeEach(() => {
    cy.visit('/profile/settings');
    cy.intercept('POST', '/api/auth/google-connect').as('googleConnect');
    cy.intercept('GET', '/api/profile/connected-accounts').as('getConnectedAccounts');
  });

  it('should successfully connect Google account to user profile', () => {
    cy.get('[data-testid="connected-accounts-section"]').should('be.visible');
    cy.get('[data-testid="google-connect-btn"]').click();

    cy.wait('@googleConnect').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    cy.get('[data-testid="google-oauth-iframe"]').should('be.visible');
    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').type('testuser@gmail.com');
      cy.get('[id="identifierNext"]').click();
      cy.get('input[type="password"]').type('testPassword123!');
      cy.get('[id="passwordNext"]').click();
    });

    cy.get('[data-testid="connection-success-message"]')
      .should('be.visible')
      .should('contain', 'Google account successfully connected');

    cy.get('[data-testid="connected-google-email"]')
      .should('contain', 'testuser@gmail.com');

    cy.get('[data-testid="remove-google-btn"]').should('be.visible');

    cy.wait('@getConnectedAccounts').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body.accounts).to.include('google');
    });
  });

  it('should handle Google account connection failure and display error message', () => {
    cy.intercept('POST', '/api/auth/google-connect', {
      statusCode: 401,
      body: { error: 'Authentication failed' }
    }).as('googleConnectFailed');

    cy.get('[data-testid="google-connect-btn"]').click();

    cy.get('[data-testid="google-oauth-iframe"]').should('be.visible');
    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').type('invalid@gmail.com');
      cy.get('[id="identifierNext"]').click();
      cy.get('[data-testid="google-error-banner"]')
        .should('be.visible')
        .should('contain', 'Invalid email or account');
    });

    cy.wait('@googleConnectFailed').then((interception) => {
      expect(interception.response.statusCode).to.equal(401);
    });

    cy.get('[data-testid="connection-error-message"]')
      .should('be.visible')
      .should('contain', 'Failed to connect Google account');

    cy.get('[data-testid="error-retry-btn"]').should('be.visible');
    cy.get('[data-testid="connected-google-email"]').should('not.exist');
  });
});

