import { test, expect } from '@playwright/test';

test.describe('Google Account Connection - User Profile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile/settings');
    await page.routeFromHAR('recorded_har.har', { notFound: 'abort' });
  });

  test('should successfully connect Google account to user profile', async ({ page }) => {
    await page.waitForLoadState('networkidle');

    const connectedAccountsSection = page.getByRole('region', { name: /connected accounts/i });
    await expect(connectedAccountsSection).toBeVisible();

    const googleConnectButton = page.getByRole('button', { name: /connect google/i });
    await expect(googleConnectButton).toBeVisible();
    await googleConnectButton.click();

    const googleOAuthFrame = page.frameLocator('[data-testid="google-oauth-iframe"]');
    const emailInput = googleOAuthFrame.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();
    await emailInput.fill('testuser@gmail.com');

    const continueButton = googleOAuthFrame.getByRole('button', { name: /next/i });
    await continueButton.click();

    const passwordInput = googleOAuthFrame.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();
    await passwordInput.fill('testPassword123!');

    const passwordContinueButton = googleOAuthFrame.getByRole('button', { name: /next/i });
    await passwordContinueButton.click();

    await page.waitForNavigation({ waitUntil: 'networkidle' });

    const successMessage = page.getByText(/google account successfully connected/i);
    await expect(successMessage).toBeVisible();

    const connectedEmail = page.getByText('testuser@gmail.com');
    await expect(connectedEmail).toBeVisible();

    const removeButton = page.getByRole('button', { name: /remove google/i });
    await expect(removeButton).toBeVisible();

    const accountList = page.locator('[data-testid="connected-accounts-list"]');
    await expect(accountList).toContainText('google');
  });

  test('should handle Google account connection failure with error message', async ({ page }) => {
    await page.route('/api/auth/google-connect', (route) => {
      route.abort('failed');
    });

    await page.waitForLoadState('networkidle');

    const googleConnectButton = page.getByRole('button', { name: /connect google/i });
    await expect(googleConnectButton).toBeVisible();
    await googleConnectButton.click();

    const googleOAuthFrame = page.frameLocator('[data-testid="google-oauth-iframe"]');
    const emailInput = googleOAuthFrame.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();
    await emailInput.fill('invalid@gmail.com');

    const continueButton = googleOAuthFrame.getByRole('button', { name: /next/i });
    await continueButton.click();

    await page.waitForTimeout(2000);

    const errorBanner = googleOAuthFrame.getByText(/invalid email or account/i);
    await expect(errorBanner).toBeVisible();

    const errorMessage = page.getByText(/failed to connect google account/i);
    await expect(errorMessage).toBeVisible();

    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    const connectedEmail = page.getByText('testuser@gmail.com');
    await expect(connectedEmail).not.toBeVisible();
  });
});

