describe('User Sessions Management', () => {
  beforeEach(() => {
    cy.visit('/user/sessions');
  });

  it('should display all active sessions and log out from a specific session', () => {
    // Intercept the API call to fetch active sessions
    cy.intercept('GET', '/api/sessions/active').as('fetchSessions');

    // Wait for sessions to load
    cy.wait('@fetchSessions');

    // Verify sessions list is visible
    cy.get('[data-testid="sessions-container"]').should('be.visible');

    // Verify at least one session is displayed
    cy.get('[data-testid="session-item"]').should('have.length.greaterThan', 0);

    // Verify session details are displayed
    cy.get('[data-testid="session-device"]').first().should('contain', 'Chrome');
    cy.get('[data-testid="session-location"]').first().should('be.visible');
    cy.get('[data-testid="session-last-active"]').first().should('contain', 'Last active');

    // Click logout button on the first session
    cy.get('[data-testid="session-logout-btn"]').first().click();

    // Intercept the logout API call
    cy.intercept('POST', '/api/sessions/*/logout').as('logoutSession');
    cy.wait('@logoutSession');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Successfully logged out');

    // Verify the session is removed from the list
    cy.get('[data-testid="session-item"]').should('have.length.lessThan', 2);
  });

  it('should handle logout failure gracefully when API returns error', () => {
    // Intercept the API call to fetch active sessions
    cy.intercept('GET', '/api/sessions/active').as('fetchSessions');
    cy.wait('@fetchSessions');

    // Mock logout endpoint to return an error
    cy.intercept('POST', '/api/sessions/*/logout', {
      statusCode: 500,
      body: { error: 'Failed to logout session' }
    }).as('logoutError');

    // Verify sessions are displayed
    cy.get('[data-testid="sessions-container"]').should('be.visible');
