test.describe('User Sessions Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user/sessions');
  });

  test('should display all active sessions and log out from a specific session', async ({ page }) => {
    // Intercept the API call to fetch active sessions
