    const sessionCount = await sessionItems.count();
    expect(sessionCount).toBeGreaterThan(0);

    // Verify session details are visible
    const deviceInfo = page.locator('[data-testid="session-device"]').first();
    await expect(deviceInfo).toContainText('Chrome');

    const locationInfo = page.locator('[data-testid="session-location"]').first();
