      route.continue();
    });

    // Click logout button
    await logoutButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/successfully logged out/i);
    await expect(successMessage).toBeVisible();

    // Verify session count decreased
    const updatedSessionItems = page.locator('[data-testid="session-item"]');
    const updatedCount = await updatedSessionItems.count();
    expect(updatedCount).toBeLessThan(sessionCount);
  });

  test('should handle logout failure gracefully when API returns error', async ({ page }) => {
    // Mock logout endpoint to return an error
    await page.route('**/api/sessions/*/logout', route => {
      route.abort('failed');
    });

    // Verify sessions are displayed
    const sessionsContainer = page.locator('[data-testid="sessions-container"]');
    await expect(sessionsContainer).toBeVisible();

    const sessionItems = page.locator('[data-testid="session-item"]');
    const initialCount = await sessionItems.count();
    expect(initialCount).toBeGreaterThan(0);

    // Verify first session is visible
    const firstSessionItem = page.locator('[data-testid="session-item"]').first();
    await expect(firstSessionItem).toBeVisible();

    // Get logout button using getByRole
    const logoutButton = page.getByRole('button', { name: /log out/i }).first();
    await expect(logoutButton).toBeEnabled();

    // Attempt to logout
    await logoutButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/failed to logout|error/i);
    await expect(errorMessage).toBeVisible();

    // Verify logout button is still available
    const retryLogoutButton = page.getByRole('button', { name: /log out/i }).first();
    await expect(retryLogoutButton).toBeVisible();

    // Verify session count is unchanged
    const unchangedSessionItems = page.locator('[data-testid="session-item"]');
    const finalCount = await unchangedSessionItems.count();
    expect(finalCount).toBe(initialCount);
  });
});

